rule"],"related_theory_ids":[]},{"id":"kb_236","taxonomy_order":58,"display_id":58,"aliases":["focusing illusion"],"related_theory_ids":["theory-c83321fd-d076-4d5c-b270-6af925c204a5","kb_1016"]},{"id":"kb_819","taxonomy_order":59,"display_id":59,"aliases":["placebo effect","プラシーボ効果"],"related_theory_ids":["kb_820","kb_137"]},{"id":"kb_429","taxonomy_order":60,"display_id":60,"aliases":["hot-cold empathy gap"],"related_theory_ids":["kb_1038"]},{"id":"kb_810","taxonomy_order":61,"display_id":61,"aliases":["optimism bias","非現実的楽観主義"],"related_theory_ids":["kb_190","kb_710"]},{"id":"kb_716","taxonomy_order":62,"display_id":62,"aliases":["law of small numbers","少数の法則"],"related_theory_ids":["kb_713","kb_714","kb_717","kb_930"]},{"id":"kb_712","taxonomy_order":63,"display_id":63,"aliases":["representativeness heuristic","代表性バイアス"],"related_theory_ids":["kb_715","kb_449"]},{"id":"kb_105","taxonomy_order":64,"display_id":64,"aliases":["Forer effect","フォアラー効果"],"related_theory_ids":[]},{"id":"kb_190","taxonomy_order":65,"display_id":65,"aliases":["planning fallacy"],"related_theory_ids":["kb_710","kb_810"]},{"id":"kb_957","title":"サブリミナル効果","summary":"意識的には識別できないほど短時間・低強度の刺激が、条件によって後続の知覚や反応に影響する現象。閾下での処理と、意識できる刺激によるプライミングを区別する。実験では刺激の見え方を測定し、反応の小さな差を調べる。隠した広告で誰の意思でも長期間支配できるという意味ではない。広告の効果を考える際は、閾値の測定、実験条件、実生活での再現性まで確認する。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":66,"display_id":66,"aliases":["subliminal perception","閾下知覚","サブリミナル知覚"],"related_theory_ids":["kb_858","kb_004","kb_958"],"canonical_id":"kb_957","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e (2020), 5.1 Sensation versus Perception"],"sources":[{"title":"Psychology 2e (2020), 5.1 Sensation versus Perception","url":"https://openstax.org/books/psychology-2e/pages/5-1-sensation-versus-perception"}],"status":"書誌確認済み","note":"閾下知覚の存在と、強力な購買操作という俗説を分離。subliminal primingは下位の実験手続きなので正式同義語にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_958","title":"信号検出理論","summary":"雑音の中で信号を見分ける判断を、感度と判定基準に分けて説明する理論。命中、見逃し、誤警報、正しい棄却を区別し、見逃しを減らす設定が誤警報を増やす場合も評価する。例えば検品で不良品を多く発見しても、正常品まで大量に除いていれば感度が高いとは限らない。注意力の良し悪しを一つの正答率だけで決めないために使える。成績は信号の出現率や損失の見積もりにも左右される。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":67,"display_id":67,"aliases":["signal detection theory"],"related_theory_ids":["kb_844","kb_214","kb_957"],"canonical_id":"kb_958","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e (2020), 5.1 Sensation versus Perception"],"sources":[{"title":"Psychology 2e (2020), 5.1 Sensation versus Perception","url":"https://openstax.org/books/psychology-2e/pages/5-1-sensation-versus-perception"}],"status":"書誌確認済み","note":"SDTは自己決定理論と衝突するため検索補助語へ。"},"quotation":null,"access_tier":"complete"},{"id":"kb_959","title":"ウェーバーの法則","summary":"刺激の違いに気づくために必要な変化量は、一定範囲では元の刺激強度に比例するという精神物理学の法則。軽い荷物には小さな増量でも気づくが、重い荷物では同じ増量が分かりにくい。弁別閾を絶対量だけでなく比率で考える手掛かりになる。値上げや音量調節の理解にも参考になるが、感覚の種類や強度の端では単純な比例が崩れる。価格への態度や満足のすべてを説明する経済法則ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":68,"display_id":68,"aliases":["Weber''s law","Weber law"],"related_theory_ids":["kb_139","kb_401","kb_969"],"canonical_id":"kb_959","legacy_ids":[],"knowledge_type":"principle","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e (2020), 5.1 Sensation versus Perception"],"sources":[{"title":"Psychology 2e (2020), 5.1 Sensation versus Perception","url":"https://openstax.org/books/psychology-2e/pages/5-1-sensation-versus-perception"}],"status":"書誌確認済み","note":"弁別閾は測定概念であり法則そのものの別名にはしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_960","title":"感覚順応","summary":"同じ刺激が続くと、その刺激に対する感覚系の反応や主観的な強さが変わる現象。部屋のにおいを入室直後ほど感じなくなることなどが例になる。変化を検出しやすくする働きがある一方、慣れた環境では刺激の存在を過小評価する可能性もある。環境確認では自分の感覚だけに頼らず、必要なら測定器や別の人の確認を使う。報酬による学習、注意の慣れ、幸福感の快楽順応とは説明の水準が異なる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":69,"display_id":69,"aliases":["sensory adaptation"],"related_theory_ids":["kb_945","kb_268"],"canonical_id":"kb_960","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e (2020), 5.1 Sensation versus Perception"],"sources":[{"title":"Psychology 2e (2020), 5.1 Sensation versus Perception","url":"https://openstax.org/books/psychology-2e/pages/5-1-sensation-versus-perception"}],"status":"書誌確認済み","note":"馴化は行動上の非連合学習。感覚順応と同義にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_961","title":"知覚的構え","summary":"期待や経験、現在の目的によって、ある解釈や特徴を知覚しやすくなる準備状態。誤植を含む文章でも文脈に沿った語として読める一方、探している物の形にこだわって目の前の別の形を見落とすことがある。検品や情報確認では、期待する答えを先に決めず、異なる見方で再確認するとよい。ただし期待が常に知覚を支配するわけではない。信念に合う証拠を集める確証バイアスより、知覚の解釈に焦点を当てる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":70,"display_id":70,"aliases":["perceptual set","知覚的セット"],"related_theory_ids":["kb_596","kb_858"],"canonical_id":"kb_961","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: perceptual-set"],"sources":[{"title":"APA Dictionary of Psychology: perceptual-set","url":"https://dictionary.apa.org/perceptual-set"}],"status":"書誌確認済み","note":"選択的知覚という広い項目を参照しつつ、期待による構えに限定して説明。"},"quotation":null,"access_tier":"complete"},{"id":"kb_962","title":"ゲシュタルトの群化原理","summary":"近接、類同、よい連続、閉合などの手掛かりにより、個々の要素をまとまりとして知覚する原理群。資料で近い位置にある項目は同じグループに、形の似た記号は同じ種類に見えやすい。図解や画面を作る際は、意味のまとまりと視覚的なまとまりを揃えるために使える。複数の原理が競合することもあり、これだけで最適なデザインが決まるわけではない。全体を重視する一般的な人生訓とは区別する。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":71,"display_id":71,"aliases":["Gestalt principles of grouping","知覚的群化"],"related_theory_ids":["kb_450","kb_746"],"canonical_id":"kb_962","legacy_ids":[],"knowledge_type":"principle","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e, 5.6 Gestalt Principles of Perception"],"sources":[{"title":"Psychology 2e, 5.6 Gestalt Principles of Perception","url":"https://openstax.org/books/psychology-2e/pages/5-6-gestalt-principles-of-perception"}],"status":"書誌確認済み","note":"知覚の原理群。ゲシュタルト療法とは別概念。"},"quotation":null,"access_tier":"complete"},{"id":"kb_963","title":"トップダウン処理・ボトムアップ処理","summary":"知覚を、既有知識や期待から解釈するトップダウンの方向と、入力された特徴から組み立てるボトムアップの方向で捉える枠組み。読みにくい文字を文脈から補うときと、未知の記号を線や形から見分けるときを比較できる。観察では先入観を点検しつつ、経験が理解を助ける面も活かす。実際の知覚は両方向が関わり、どちらかだけが正しいわけではない。経営のトップダウン・ボトムアップ方式を指す用語とは異なる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":72,"display_id":72,"aliases":["top-down and bottom-up processing"],"related_theory_ids":["kb_858","kb_450"],"canonical_id":"kb_963","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e (2020), 5.1 Sensation versus Perception"],"sources":[{"title":"Psychology 2e (2020), 5.1 Sensation versus Perception","url":"https://openstax.org/books/psychology-2e/pages/5-1-sensation-versus-perception"}],"status":"書誌確認済み","note":"一つの比較枠組みとして収録。片方だけの語は関連検索語にする。"},"quotation":null,"access_tier":"complete"},{"id":"kb_964","title":"予測符号化理論","summary":"上位の処理が下位の入力を予測し、予測と実際の入力の差を使って内部モデルを更新するという説明枠組み。曖昧な図が文脈によって違って見えることを、単なる受動的な受信ではなく予測と修正の過程として考える。思い込みを点検するときは、予測に合わなかった情報にも注意を向ける手掛かりになる。ただし日常の助言は枠組みからの応用例で、脳の全機能が単一の予測算法で説明済みという意味ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":73,"display_id":73,"aliases":["predictive coding"],"related_theory_ids":["kb_570","kb_450"],"canonical_id":"kb_964","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Rajesh P. N. Rao / Dana H. Ballard","works":["Predictive coding in the visual cortex (1999)"],"sources":[{"title":"Predictive coding in the visual cortex (1999)","url":"https://pubmed.ncbi.nlm.nih.gov/10195184/"}],"status":"書誌確認済み","note":"視覚皮質の計算モデルを起点とする。自由エネルギー原理そのものとは同義にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_966","title":"アフォーダンス","summary":"環境が、ある身体や能力をもつ行為者に対して提供する行為の可能性。腰掛けられる高さの段差は大人には座る可能性を与えても、小さな子には同じ使い方を提供しない場合がある。道具や場所を考える際、物の形だけでなく使う人との関係を見る視点になる。「押す」と書いた表示は行為を伝える手掛かりであり、可能性そのものとは区別する。望ましい行動を必ず起こさせる力や、見た目の分かりやすさだけを指す語ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":74,"display_id":74,"aliases":["affordance"],"related_theory_ids":["kb_528","kb_178"],"canonical_id":"kb_966","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: affordance"],"sources":[{"title":"APA Dictionary of Psychology: affordance","url":"https://dictionary.apa.org/affordance"}],"status":"書誌確認済み","note":"J. J. Gibsonの生態学的知覚論。知覚されたアフォーダンスやシグニファイアと区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_969","title":"絶対閾","summary":"統制した測定条件で、刺激の存在を一定の割合、通常は半数の試行で検出できる最小の強度。音量を少しずつ変えて聞こえたかを繰り返し尋ねると、毎回必ず聞こえる境界ではなく検出確率として捉えられる。表示や警告の設計では、測定条件と利用者の違いを確認するために役立つ。疲労、雑音、期待でも結果は変わる。二つの刺激の違いを検出する弁別閾とは別で、全員共通の固定値ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":75,"display_id":75,"aliases":["absolute threshold","感覚閾"],"related_theory_ids":["kb_872","kb_959"],"canonical_id":"kb_969","legacy_ids":[],"knowledge_type":"principle","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e (2020), 5.1 Sensation versus Perception"],"sources":[{"title":"Psychology 2e (2020), 5.1 Sensation versus Perception","url":"https://openstax.org/books/psychology-2e/pages/5-1-sensation-versus-perception"}],"status":"書誌確認済み","note":"心理物理学の測定概念。無意識の処理の有無を単独で確定する指標ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_971","title":"心的回転","summary":"物体や図形の向きを頭の中で変え、同じ形かどうかを判断する心的操作。異なる角度から描かれた立体を比較する実験では、角度差が大きいほど判断時間が長くなる傾向が示された。家具の配置や図面の理解で、向きを変えた姿を想像することが身近な例になる。空間課題を考える基礎概念だが、成績は経験、方略、課題の形式で変わる。空間能力や知能全体を一つの課題で決めつける指標ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":76,"display_id":76,"aliases":["mental rotation"],"related_theory_ids":["kb_450","kb_742"],"canonical_id":"kb_971","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Roger N. Shepard / Jacqueline Metzler","works":["Mental rotation of three-dimensional objects (1971)"],"sources":[{"title":"Mental rotation of three-dimensional objects (1971)","url":"https://pubmed.ncbi.nlm.nih.gov/5540314/"}],"status":"書誌確認済み","note":"追加発見候補から採用。頻度錯覚の代替。"},"quotation":null,"access_tier":"complete"},{"id":"kb_981","title":"二重過程理論","summary":"推論や判断を、自律的で素早い処理と、作業記憶を使う検討的な処理の違いから説明する理論群。見慣れた答えを即座に選ぶときと、その答えを計算や規則で点検するときを比較できる。重要な判断では直感の根拠を確認する時間を設ける手掛かりになる。脳に二つの独立した箱があるという主張ではなく、速さだけで処理を判別できるわけでもない。直感が常に誤りで、熟考が常に正しいという意味でもない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":77,"display_id":77,"aliases":["dual-process theory","dual-process theories"],"related_theory_ids":["kb_754","kb_430","kb_745"],"canonical_id":"kb_981","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Jonathan St B. T. Evans / Keith E. Stanovich","works":["Dual-Process Theories of Higher Cognition (2013)"],"sources":[{"title":"Dual-Process Theories of Higher Cognition (2013)","url":"https://doi.org/10.1177/1745691612460685"}],"status":"書誌確認済み","note":"単一理論ではなく理論群。喪失の二重過程モデルとは異なる。"},"quotation":null,"access_tier":"complete"},{"id":"kb_982","title":"属性置換","summary":"難しい問いを判断するとき、答えやすい別の属性で知らずに置き換えて答えること。「この計画は成功するか」を「担当者は好ましいか」で判断する場合などがある。利用可能な情報が、本来求められた評価を代用してしまう仕組みとして考える。判断を点検するときは、今評価している属性と、本来の問いを別々に書き出す。すべての簡便な判断が属性置換とは限らず、適切な代替指標が役立つ場合もある。好感そのものや確証バイアスと同義ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":78,"display_id":78,"aliases":["attribute substitution"],"related_theory_ids":["kb_003","kb_430","kb_597"],"canonical_id":"kb_982","legacy_ids":[],"knowledge_type":"heuristic","provenance":{"attribution":"Daniel Kahneman / Shane Frederick","works":["属性置換のモデル；Kahneman, Maps of Bounded Rationality (2003)"],"sources":[{"title":"属性置換のモデル；Kahneman, Maps of Bounded Rationality (2003)","url":"https://kahneman.scholar.princeton.edu/document/8"}],"status":"書誌確認済み","note":"容易な属性への置換という機序を収録。"},"quotation":null,"access_tier":"complete"},{"id":"kb_983","title":"信念バイアス","summary":"結論がもっともらしいかどうかによって、論証の論理的な妥当性の判断が影響される傾向。日常的に正しそうな結論だと、前提からその結論が導けていなくても受け入れやすくなる。議論を読む際は、結論への賛否と、前提を仮に認めたとき推論が成立するかを分けて確かめる。信念に合う情報を探す確証バイアスより、提示済みの推論の評価に焦点を当てる。内容への知識が常に無益という意味ではなく、形式と事実確認の両方が必要である。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":79,"display_id":79,"aliases":["belief bias"],"related_theory_ids":["kb_596","kb_929"],"canonical_id":"kb_983","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Jonathan St B. T. Evans / Julie L. Barston / Paul Pollard","works":["On the conflict between logic and belief in syllogistic reasoning (1983)"],"sources":[{"title":"On the conflict between logic and belief in syllogistic reasoning (1983)","url":"https://doi.org/10.3758/BF03196976"}],"status":"書誌確認済み","note":"論理的妥当性と内容の信じやすさの実験的対立。"},"quotation":null,"access_tier":"complete"},{"id":"kb_984","title":"認知欲求","summary":"努力を要する思考に取り組み、それを楽しむ傾向の個人差。複雑な問題の理由を調べることを好む人と、要点だけを早く知りたい人の違いなどに現れる。説明を作る際は、根拠や比較を求める相手に詳細を用意するなど、関心に応じた伝え方を考えられる。ただし知能や知識量そのものを測る概念ではなく、疲労や関心によっても取り組み方は変わる。結論を早く確定したい認知的閉鎖欲求とは異なる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":80,"display_id":80,"aliases":["need for cognition"],"related_theory_ids":["kb_881"],"canonical_id":"kb_984","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: need-for-cognition"],"sources":[{"title":"APA Dictionary of Psychology: need-for-cognition","url":"https://dictionary.apa.org/need-for-cognition"}],"status":"書誌確認済み","note":"CacioppoとPettyらの個人差構成概念。能力や優劣の診断にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_985","title":"イデオモーター効果","summary":"動作についての考えや期待が、意図していると自覚しにくい小さな運動に結び付く現象。手に持った振り子が、予想した方向へわずかに動くことなどが例になる。本人が動かした感覚を持たないことは、外部の不思議な力が働いた証拠にはならない。体験を検討する際は、期待や微細な身体運動を分けて確かめる。行動の模倣や広い社会的プライミングと同義ではなく、あらゆる考えがそのまま実行されるという主張でもない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-c","taxonomy_order":81,"display_id":81,"aliases":["ideomotor effect","観念運動"],"related_theory_ids":["kb_391","kb_231"],"canonical_id":"kb_985","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: ideomotor-activity"],"sources":[{"title":"APA Dictionary of Psychology: ideomotor-activity","url":"https://dictionary.apa.org/ideomotor-activity"}],"status":"書誌確認済み","note":"観念と微細な運動の関係。念力等を支持する概念として扱わない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_023","taxonomy_order":1,"display_id":82,"aliases":["emotional contagion","情動伝染"],"related_theory_ids":["theory-62543145-f91d-448d-aece-2a44802164f8"]},{"id":"kb_885","taxonomy_order":2,"display_id":83,"aliases":["two-factor theory of emotion","シャクター＝シンガー理論"],"related_theory_ids":["kb_028","kb_905","kb_027","kb_886","kb_988"]},{"id":"kb_886","taxonomy_order":3,"display_id":84,"aliases":["James–Lange theory","James-Lange theory"],"related_theory_ids":["kb_027","kb_228","kb_905","kb_885","kb_988"]},{"id":"kb_905","taxonomy_order":4,"display_id":85,"aliases":["Cannon–Bard theory","Cannon-Bard theory"],"related_theory_ids":["kb_027","kb_228","kb_885","kb_886","kb_988"]},{"id":"kb_602","taxonomy_order":5,"display_id":86,"aliases":["broaden-and-build theory"],"related_theory_ids":[]},{"id":"kb_234","taxonomy_order":6,"display_id":87,"aliases":[],"related_theory_ids":