","kb_1080"]},{"id":"kb_238","taxonomy_order":42,"display_id":123,"aliases":["stress inoculation training"],"related_theory_ids":[]},{"id":"kb_272","taxonomy_order":43,"display_id":124,"aliases":["logotherapy"],"related_theory_ids":[]},{"id":"kb_222","taxonomy_order":44,"display_id":125,"aliases":[],"related_theory_ids":[]},{"id":"kb_227","taxonomy_order":45,"display_id":126,"aliases":["affect labeling"],"related_theory_ids":["kb_986","kb_987"]},{"id":"kb_217","taxonomy_order":46,"display_id":127,"aliases":[],"related_theory_ids":[]},{"id":"kb_226","taxonomy_order":47,"display_id":128,"aliases":["self-distancing","自己距離化"],"related_theory_ids":[]},{"id":"kb_224","taxonomy_order":48,"display_id":129,"aliases":["decentering"],"related_theory_ids":["kb_986"]},{"id":"kb_230","taxonomy_order":49,"display_id":130,"aliases":[],"related_theory_ids":["kb_725"]},{"id":"kb_223","taxonomy_order":50,"display_id":131,"aliases":["cognitive defusion"],"related_theory_ids":[]},{"id":"kb_580","taxonomy_order":51,"display_id":132,"aliases":[],"related_theory_ids":[]},{"id":"kb_578","taxonomy_order":52,"display_id":133,"aliases":["expressive writing"],"related_theory_ids":[]},{"id":"kb_237","taxonomy_order":53,"display_id":134,"aliases":["defensive pessimism"],"related_theory_ids":["kb_728"]},{"id":"kb_229","taxonomy_order":54,"display_id":135,"aliases":[],"related_theory_ids":["kb_986","kb_987"]},{"id":"kb_202","taxonomy_order":55,"display_id":136,"aliases":[],"related_theory_ids":["kb_901"]},{"id":"kb_986","title":"感情調整プロセスモデル","summary":"感情が生じて表れるまでの過程に沿って、状況選択、状況修正、注意の配分、認知の変化、反応の調整を区別するモデル。苦手な会議では、準備や席の選び方を変えることと、会議中に表情を抑えることは介入する段階が違う。感情を我慢する以外の選択肢を探すために使える。ただし各方略が常に良い・悪いわけではなく、目的や対人状況に応じて機能が変わる。感情を完全に消す方法を示すものではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-e","taxonomy_order":56,"display_id":137,"aliases":["process model of emotion regulation"],"related_theory_ids":["kb_229","kb_227","kb_224"],"canonical_id":"kb_986","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"James J. Gross","works":["The Emerging Field of Emotion Regulation (1998)"],"sources":[{"title":"The Emerging Field of Emotion Regulation (1998)","url":"https://doi.org/10.1037/1089-2680.2.3.271"}],"status":"書誌確認済み","note":"調整の時点を整理するモデル。個別技法の効果保証ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_987","title":"情動粒度","summary":"自分の感情経験を、単に良い・悪いだけでなく、焦り、落胆、怒りなどとして細かく区別する程度。仕事で同じ「つらい」でも、期限への焦りか、扱われ方への怒りかで必要な対応は違う。感情を記録するとき、状況に合う言葉を探すための視点になる。研究では日々の報告のパターンなどから測り、語彙の多さだけと同一視しない。精神的健康との関連はあるが、言葉を増やせば必ず症状が改善するという因果の保証ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-e","taxonomy_order":57,"display_id":138,"aliases":["emotional granularity","emotion differentiation","感情粒度"],"related_theory_ids":["kb_227","kb_229"],"canonical_id":"kb_987","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Katie Hoemann / Lisa Feldman Barrett / Karen S. Quigley","works":["Emotional Granularity Increases With Intensive Ambulatory Assessment (2021)"],"sources":[{"title":"Emotional Granularity Increases With Intensive Ambulatory Assessment (2021)","url":"https://pubmed.ncbi.nlm.nih.gov/34393942/"}],"status":"書誌確認済み","note":"構成概念と関連の確認。介入の万能な効能にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_988","title":"感情構成理論","summary":"感情を、身体内部の感覚、過去の経験、概念、状況に基づいて脳が構成する経験として捉える理論。同じ動悸でも、発表前には不安、競技前には高揚として経験することを考える枠組みになる。自分の感情の意味を考える際、身体と文脈の両方に目を向けられる。ただし感情が好きに選べる、身体反応が存在しないという意味ではない。基本情動説などと議論が続く理論であり、すべての感情研究が合意した最終説明ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-e","taxonomy_order":58,"display_id":139,"aliases":["theory of constructed emotion","構成主義的感情理論"],"related_theory_ids":["kb_885","kb_886","kb_905"],"canonical_id":"kb_988","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Lisa Feldman Barrett","works":["The theory of constructed emotion (2017)"],"sources":[{"title":"The theory of constructed emotion (2017)","url":"https://doi.org/10.1093/scan/nsw154"}],"status":"書誌確認済み","note":"感情の分類・生成についての理論的立場。確定した唯一の機序とはしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_989","title":"社会的評価不安","summary":"他者からどう評価されるかへの心配や、否定的に見られることへの不安。発表で内容より失敗の印象ばかり気になり、質問を避けることなどが例になる。行動を振り返るとき、実際の評価、予測した評価、その予測から取った回避行動を分けて整理できる。社会的状況の不快感や否定的評価への恐れを測る研究があるが、これだけで病気を診断する概念ではない。程度や生活上の影響は人によって異なり、現実の不公正な評価環境も見落とさない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-e","taxonomy_order":59,"display_id":140,"aliases":["social-evaluative anxiety"],"related_theory_ids":["kb_232","kb_207","kb_816"],"canonical_id":"kb_989","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"David Watson / Ronald Friend","works":["Measurement of social-evaluative anxiety (1969)"],"sources":[{"title":"Measurement of social-evaluative anxiety (1969)","url":"https://pubmed.ncbi.nlm.nih.gov/5810590/"}],"status":"書誌確認済み","note":"fear of negative evaluationは測定上の側面であり、全体の厳密な同義語にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_169","taxonomy_order":1,"display_id":141,"aliases":["self-efficacy"],"related_theory_ids":["kb_727","kb_728","kb_735","kb_750","kb_904","kb_941","kb_948","kb_804","kb_1027","kb_1032","kb_1034","kb_1035","kb_1036"]},{"id":"kb_906","taxonomy_order":2,"display_id":142,"aliases":["PERMA model","パーマモデル"],"related_theory_ids":["kb_736","kb_243","kb_564"]},{"id":"kb_259","taxonomy_order":3,"display_id":143,"aliases":[],"related_theory_ids":["kb_806"]},{"id":"kb_257","taxonomy_order":4,"display_id":144,"aliases":["self-discrepancy theory"],"related_theory_ids":["kb_990"]},{"id":"kb_020","taxonomy_order":5,"display_id":145,"aliases":[],"related_theory_ids":[]},{"id":"kb_420","taxonomy_order":6,"display_id":146,"aliases":["self-perception theory"],"related_theory_ids":["kb_869","kb_897"]},{"id":"kb_869","taxonomy_order":7,"display_id":147,"aliases":["Proteus effect","プロテウス・エフェクト"],"related_theory_ids":["kb_420","kb_111"]},{"id":"kb_883","taxonomy_orde