b_1005"]},{"id":"kb_121","taxonomy_order":42,"display_id":182,"aliases":[],"related_theory_ids":[]},{"id":"kb_221","taxonomy_order":43,"display_id":183,"aliases":[],"related_theory_ids":[]},{"id":"kb_262","taxonomy_order":44,"display_id":184,"aliases":[],"related_theory_ids":[]},{"id":"kb_990","title":"自尊心の随伴性","summary":"自分の価値が、他者の承認、競争での成功、外見など特定の領域の結果にどれほど依存しているかを捉える枠組み。仕事の失敗を能力の一部への評価でなく「自分には価値がない」と受け止める場合などが例になる。自尊心の高低だけでなく、何に支えられ、どんな出来事で揺れるかを見直す手掛かりになる。達成に価値を置くこと自体が必ず有害なわけではない。依存する領域や、その領域での経験によって影響は変わる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-s","taxonomy_order":45,"display_id":185,"aliases":["contingencies of self-worth","自己価値の随伴性"],"related_theory_ids":["kb_257","kb_815","kb_264"],"canonical_id":"kb_990","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Jennifer Crocker / Connie T. Wolfe","works":["Contingencies of self-worth (2001)"],"sources":[{"title":"Contingencies of self-worth (2001)","url":"https://pubmed.ncbi.nlm.nih.gov/11488379/"}],"status":"書誌確認済み","note":"自尊心の水準や不安定さそのものとは分ける。"},"quotation":null,"access_tier":"complete"},{"id":"kb_991","title":"多次元的完璧主義","summary":"完璧さへの要求を一種類とせず、自分への要求、他者への要求、他者から要求されている感覚などに分けて捉える枠組み。資料を何度も直す人でも、自分の基準の高さと「少しでも誤ると見放される」という受け止めでは対応が違う。基準、失敗への反応、対人期待を分けて振り返るために使える。異なる研究者の尺度には別の次元構成もあり、単一の分類で人を断定しない。丁寧さや高い目標がすべて問題だという意味ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-s","taxonomy_order":46,"display_id":186,"aliases":["multidimensional perfectionism"],"related_theory_ids":["kb_727","kb_728","kb_264"],"canonical_id":"kb_991","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Paul L. Hewitt / Gordon L. Flett","works":["Perfectionism in the self and social contexts (1991)"],"sources":[{"title":"Perfectionism in the self and social contexts (1991)","url":"https://pubmed.ncbi.nlm.nih.gov/2027080/"}],"status":"書誌確認済み","note":"Hewitt–Flettの三次元を例示。Frost尺度との同一視を避ける。"},"quotation":null,"access_tier":"complete"},{"id":"kb_992","title":"達成動機理論","summary":"優れた基準に照らして成功したい動機と、失敗を避けたい動機が、挑戦や課題選択にどう関わるかを説明する理論群。成功を試したい人が適度に難しい課題を選ぶ一方、失敗を強く恐れる人が極端に容易な課題へ寄る場合などを考える。目標設定では、難度だけでなく成功の見込みや失敗の意味づけを確かめる。すべての行動を競争心で説明するものではなく、動機、状況、文化、使うモデルによって予測は異なる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-s","taxonomy_order":47,"display_id":187,"aliases":["achievement motivation theory"],"related_theory_ids":["kb_750","kb_187","kb_728"],"canonical_id":"kb_992","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"John W. Atkinson","works":["Motivational determinants of risk-taking behavior (1957)"],"sources":[{"title":"Motivational determinants of risk-taking behavior (1957)","url":"https://doi.org/10.1037/h0043445"}],"status":"書誌確認済み","note":"Atkinsonの成功追求と失敗回避を中心に説明。期待価値一般と同義にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_036","taxonomy_order":1,"display_id":188,"aliases":["attachment theory"],"related_theory_ids":["kb_924"]},{"id":"kb_009","taxonomy_order":2,"display_id":189,"aliases":["social penetration theory"],"related_theory_ids":["kb_008"]},{"id":"kb_008","taxonomy_order":3,"display_id":190,"aliases":[],"related_theory_ids":["kb_009","kb_1008","kb_1047"]},{"id":"kb_030","taxonomy_order":4,"display_id":191,"aliases":["social exchange theory"],"related_theory_ids":["kb_031"]},{"id":"kb_031","taxonomy_order":5,"display_id":192,"aliases":["equity theory"],"related_theory_ids":["kb_030","kb_1043"]},{"id":"kb_033","taxonomy_order":6,"display_id":193,"aliases":["interdependence theory"],"related_theory_ids":["kb_822","kb_035"]},{"id":"kb_034","taxonomy_order":7,"display_id":194,"aliases":[],"related_theory_ids":["kb_923"]},{"id":"kb_822","taxonomy_order":8,"display_id":195,"aliases":["triangular theory of love","愛情の三角理論"],"related_theory_ids":["kb_765","kb_033","kb_923","theory-386c4608-d46d-4782-b912-36c85aa8024d"]},{"id":"kb_004","taxonomy_order":9,"display_id":196,"aliases":["mere exposure effect"],"related_theory_ids":["kb_7