y_id":289,"aliases":["narrative transportation","物語への移入"],"related_theory_ids":["kb_784","kb_718"]},{"id":"kb_861","taxonomy_order":103,"display_id":290,"aliases":["two-step flow of communication","二段階の流れ"],"related_theory_ids":["kb_781","kb_783"]},{"id":"kb_389","taxonomy_order":104,"display_id":291,"aliases":[],"related_theory_ids":[]},{"id":"kb_461","taxonomy_order":105,"display_id":292,"aliases":["情報源信頼性モデル","source credibility model","source credibility"],"related_theory_ids":["kb_784","kb_785","kb_857","kb_935"]},{"id":"kb_785","taxonomy_order":106,"display_id":293,"aliases":["heuristic-systematic model","HSM","ヒューリスティックシステマティックモデル","HSM／ヒューリスティック・システマティック・モデル","ヒューリスティック系統的モデル"],"related_theory_ids":["kb_461","kb_784"]},{"id":"kb_923","taxonomy_order":107,"display_id":294,"aliases":["ロミオ・ジュリエット効果","Romeo and Juliet effect","ロミオとジュリエット効果"],"related_theory_ids":["kb_898","kb_034","kb_822","kb_050"]},{"id":"kb_924","taxonomy_order":108,"display_id":295,"aliases":["adult attachment styles","成人の愛着スタイル","恋愛の愛着スタイル"],"related_theory_ids":["kb_816","kb_012","kb_036"]},{"id":"kb_928","taxonomy_order":109,"display_id":296,"aliases":["empathic accuracy","共感的精度"],"related_theory_ids":["kb_404","kb_818","kb_233"]},{"id":"kb_1007","title":"対人距離理論","summary":"対人場面で空間や距離がどう使われ、関係や文化と結び付くかを考える枠組み。初対面で近づきすぎると落ち着かない人がいる一方、同じ距離でも親密さや状況により受け止めは変わる。会話や席の配置では、相手の反応と場所の制約を確かめ、距離を調整する手掛かりになる。親密・個体・社会・公衆距離という整理は、全文化や全員に共通する厳密な物差しではない。距離だけから好意や性格を読み取らない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-i","taxonomy_order":110,"display_id":297,"aliases":["proxemics","プロクセミックス"],"related_theory_ids":["kb_037","kb_092","kb_474"],"canonical_id":"kb_1007","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Edward T. Hall","works":["The Hidden Dimension (1966；参照版)"],"sources":[{"title":"The Hidden Dimension (1966；参照版)","url":"https://www.penguinrandomhouse.com/books/73818/the-hidden-dimension-by-edward-t-hall/"}],"status":"書誌確認済み","note":"Hallの空間利用の研究。単なる心理的な近さとは区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1008","title":"ジョハリの窓","summary":"自分が知っているか、他者が知っているかの二軸で、自己理解を開放・盲点・秘密・未知の四領域に整理するモデル。自分では普通だと思う振る舞いを同僚から指摘されると、盲点を知る機会になる。振り返りでは具体的なフィードバックを求め、必要に応じて自己開示するために使える。すべてを開示するほど良いわけではなく、秘密や境界を守ることも大切である。四領域を精密に測定する診断法や、他人の内面を透視する方法ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-i","taxonomy_order":111,"display_id":298,"aliases":["Johari window"],"related_theory_ids":["kb_008","kb_115","kb_394"],"canonical_id":"kb_1008","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Joseph Luft / Harrington Ingham；Curtin University（参照解説）","works":["Looking through the Johari Window"],"sources":[{"title":"Looking through the Johari Window","url":"https://www.curtin.edu.au/news/oasis-news/looking-through-the-johari-window/"}],"status":"書誌確認済み","note":"教育・対人理解用モデル。自己開示を強制しない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_058","taxonomy_order":1,"display_id":299,"aliases":["social identity theory"],"related_theory_ids":["kb_732","kb_882","kb_993","kb_1002","kb_1004"]},{"id":"kb_059","taxonomy_order":2,"display_id":300,"aliases":["self-categorization theory"],"related_theory_ids":[]},{"id":"kb_062","taxonomy_order":3,"display_id":301,"aliases":[],"related_theory_ids":["kb_926"]},{"id":"kb_060","taxonomy_order":4,"display_id":302,"aliases":[],"related_theory_ids":["kb_925","kb_926","kb_927"]},{"id":"kb_061","taxonomy_order":5,"display_id":303,"aliases":[],"related_theory_ids":[]},{"id":"kb_063","taxonomy_order":6,"display_id":304,"aliases":[],"related_theory_ids":["kb_888","theory-b16cc75c-68d0-4873-b989-2ed788bd404b"]},{"id":"kb_888","taxonomy_order":7,"display_id":305,"aliases":["social impact theory","社会的影響力理論"],"related_theory_ids":["kb_063","kb_072","kb_073"]},{"id":"kb_459","taxonomy_order":8,"display_id":306,"aliases":[],"related_theory_ids":["kb_734"]},{"id":"kb_734","taxonomy_order":9,"display_id":307,"aliases":["informational social influence","informational influence","情報的影響"],"related_theory_ids":["kb_459","kb_067"]},{"id":"kb_104","taxonomy_order":10,"display_id":308,"aliases":[],"related_theory_ids":["kb_729"]},{"id":"kb_072","taxonomy_order":11,"display_id":309,"aliases":["bystander effect"],"related_theory_ids":["kb_888","kb_073"]},{"id":"kb_477","taxonomy_order":12,"display_id":310,"aliases":[],"related_theory_ids":[]},{"id":"kb_733","taxonomy_order":13,"display_id":311,"aliases":["obedience to authority","ミルグラム実験","服従実験"],"related_theory_ids":["kb_452","kb_073"]},{"id":"kb_731","taxonomy_order":14,"display_id":312,"aliases":["stereotype threat","ステレオタイプ・スレット"],"related_theory_ids":["kb_074","kb_123","kb_997"]},{"id":"kb_106","taxonomy_order":15,"display_id":313,"aliases":[],"related_theory_ids":["kb_729","kb_782","kb_998","kb_1001"]},{"id":"kb_782","taxonomy_order":16,"display_id":314,"aliases":["threshold model of collective behavior","集団行動の閾値モデル"],"related_theory_ids":["kb_781","kb_106","kb_852"]},{"id":"kb_485","taxonomy_order":17,"display_id":315,"aliases":[],"related_theory_ids":["kb_925","kb_1002"]},{"id":"kb_481","taxonomy_order":18,"display_id":316,"aliases":[],"related_theory_ids":[]},{"id":"kb_473","taxonomy_order":19,"display_id":317,"aliases":[],"related_theory_ids":["kb_995","kb_996","kb_998"]},{"id":"kb_067","taxonomy_order":20,"display_id":318,"aliases":["pluralistic ignorance"],"related_theory_ids":["kb_707","kb_734","kb_068"]},{"id":"kb_732","taxonomy_order":21,"display_id":319,"aliases":["deindividuation","没個性化"],"related_theory_ids":["kb_058","kb_073"]},{"id":"kb_066","taxonomy_order":22,"display_id":320,"aliases":[],"related_theory_ids":[]},{"id":"kb_484","taxonomy_order":23,"display_id":321,"aliases":[],"related_theory_ids":[]},{"id":"kb_457","taxonomy_order":24,"display_id":322,"aliases":[],"related_theory_ids":[]},{"id":"kb_458","taxonomy_order":25,"display_id":323,"aliases":[],"related_theory_ids":[]},{"id":"kb_470","taxonomy_order":26,"display_id":324,"aliases":[],"related_theory_ids":["kb_730","kb_996","kb_997","kb_1002"]},{"id":"kb_729","taxonomy_order":27,"display_id":325,"aliases":["bandwagon effect","バンドワゴン・エフェクト"],"related_theory_ids":["kb_104","kb_106","kb_1021"]},{"id":"kb_762","taxonomy_order":28,"display_id":326,"aliases":["Hawthorne effect","ホーソン実験"],"related_theory_ids":["kb_538","kb_123","kb_933"]},{"id":"kb_925","taxonomy_order":29,"display_id":327,"aliases":["contact hypothesis","intergroup contact theory","集団間接触理論"],"related_theory_ids":["kb_060","kb_485","kb_004","kb_926"]},{"id":"kb_926","taxonomy_order":30,"display_id":328,"aliases":["realistic conflict theory","現実的集団葛藤理論"],"related_theory_ids":["kb_062","kb_060","kb_925","kb_795"]},{"id":"kb_927","taxonomy_order":31,"display_id":329,"aliases":["stereotype content model","SCM"],"related_theory_ids":["kb_060","kb_119","kb_003","kb_993","kb_997","kb_1000","kb_1001","kb_1006"]},{"id":"kb_993","title":"道徳基盤理論","summary":"道徳判断の違いを、ケア、公正、忠誠、権威、神聖など複数の関心の重みから説明する理論。ある提案を一方は公平さ、他方は共同体の秩序から評価すると、同じ結論を求めても対話が噛み合わない場合がある。反対意見を悪意と決めず、何を守りたいのかを聞く視点になる。基盤の数や測定、文化への一般化には議論があり、人を固定した政治的型へ分ける道具ではない。価値の違いを説明することと、その行為を倫理的に正当化することも別である。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":32,"display_id":330,"aliases":["moral foundations theory"],"related_theory_ids":["kb_058","kb_927"],"canonical_id":"kb_993","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Jonathan Haidt / Jesse Graham / Craig Josephほか","works":["Moral Foundations Theory（研究者の公式解説）"],"sources":[{"title":"Moral Foundations Theory（研究者の公式解説）","url":"https://moralfoundations.org/"}],"status":"書誌確認済み","note":"基盤の構成は改訂されている。特定の個人・文化の診断に使わない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_994","title":"道徳的切り離し","summary":"通常は働く道徳的な自己抑制を、正当化や責任の分散、被害の軽視などで外してしまう過程。相手を傷つける言動でも「会社のため」「皆がやっている」と説明すると、自分を責めずに続けられる場合がある。組織や日常の判断では、目的の説明と実際の被害、誰が決めたかを分けて確認する手掛かりになる。本人に罪悪感がないことを、被害がない証拠にしない。違反を必ず生む性格特性や、単なる認知的不協和の別名ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":33,"display_id":331,"aliases":["moral disengagement","道徳的不活性化"],"related_theory_ids":["kb_265","kb_073","kb_883"],"canonical_id":"kb_994","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Albert Bandura","works":["Moral disengagement in the perpetration of inhumanities (1999)"],"sources":[{"title":"Moral disengagement in the perpetration of inhumanities (1999)","url":"https://pubmed.ncbi.nlm.nih.gov/15661671/"}],"status":"書誌確認済み","note":"責任転嫁、婉曲表現、非人間化などの過程を扱う。"},"quotation":null,"access_tier":"complete"},{"id":"kb_995","title":"ルーピング効果","summary":"人を分類する概念が当事者の自己理解や行動を変え、その変化が分類自体の理解や運用へ戻るという相互作用。ある集団に名称が与えられると、当事者がそれに応答し、分類を研究・管理する側も定義を修正する場合がある。診断名や人物像を扱うとき、分類を受ける人の反応まで含めて考える視点になる。期待が現実になる自己成就予言と重なる面はあるが、分類と人が共に変わる過程に焦点がある。あらゆる分類で同じ影響が起きるとは限らない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":34,"display_id":332,"aliases":["looping effect","人間種のルーピング効果"],"related_theory_ids":["kb_473","kb_246","kb_996"],"canonical_id":"kb_995","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Ian Hacking","works":["The looping effects of human kinds, Causal Cognition (1995/1996参照版)"],"sources":[{"title":"The looping effects of human kinds, Causal Cognition (1995/1996参照版)","url":"https://doi.org/10.1093/acprof:oso/9780198524021.003.0012"}],"status":"書誌確認済み","note":"社会科学の分類と分類される人の相互作用。自己成就予言の同義語ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_996","title":"ラベリング理論","summary":"ある行為や人が逸脱と名付けられ、周囲からそう扱われる過程が、その後の立場や自己理解、行動に影響することに注目する社会学の理論。失敗した新人を「問題のある人」と呼び続けると、学ぶ機会や参加が制限される場合などを考えられる。行為の評価と、人の全体への固定した名付けを分ける視点になる。ラベルだけが逸脱の原因という主張ではなく、実際の行為や環境条件も必要である。感情に名前を付ける感情ラベリングとは別概念。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":35,"display_id":333,"aliases":["labeling theory","labelling theory"],"related_theory_ids":["kb_473","kb_470","kb_246","kb_995"],"canonical_id":"kb_996","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Howard S. Becker","works":["Outsiders (1963；出版社の参照版)"],"sources":[{"title":"Outsiders (1963；出版社の参照版)","url":"https://www.simonandschuster.com/books/Outsiders/Howard-S-Becker/9781982106225"}],"status":"書誌確認済み","note":"社会的反応への着目。Edwin Lemert等にも先行的貢献があり、Becker単独の発明としない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_997","title":"スティグマ","summary":"ある属性が社会的に否定的な意味と結び付き、その人全体への評価や扱いを不利にすること。病歴や出自を知っただけで能力まで低く見積もる場合などがある。個人の思い込みだけでなく、情報の管理、関係、機会へのアクセスまで含めて理解する。対人場面では必要な情報と偏見を分け、本人の開示の意思を尊重する。属性そのものが本質的に劣っているという意味ではなく、文化や制度、状況によって何が不名誉とされるかは変わる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":36,"display_id":334,"aliases":["stigma","社会的烙印"],"related_theory_ids":["kb_470","kb_927","kb_731"],"canonical_id":"kb_997","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Erving Goffman","works":["Stigma: Notes on the Management of Spoiled Identity (1963)"],"sources":[{"title":"Stigma: Notes on the Management of Spoiled Identity (1963)","url":"https://www.simonandschuster.com/books/Stigma/Erving-Goffman/9781439188330"}],"status":"書誌確認済み","note":"社会関係上の評価として扱い、対象者の欠陥という説明を避ける。"},"quotation":null,"access_tier":"complete"},{"id":"kb_998","title":"トマスの定理","summary":"人々がある状況を現実だと定義すれば、その定義に基づいた行動は現実の結果をもつ、という社会学の命題。実際には起きていない不足の噂でも、人々が買いだめすれば店頭の不足につながる場合がある。事実を確かめるだけでなく、どのように状況が理解され、行動が変わるかを見る手掛かりになる。思えば何でも実現するという法則ではなく、誤った認識が常に自らを実現するとも限らない。自己成就予言より広い、状況の定義と結果の関係を扱う。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":37,"display_id":335,"aliases":["Thomas theorem","トーマスの定理"],"related_theory_ids":["kb_473","kb_106"],"canonical_id":"kb_998","legacy_ids":[],"knowledge_type":"principle","provenance":{"attribution":"William I. Thomas / Dorothy Swaine Thomas","works":["The Child in America (1928), p.572"],"sources":[{"title":"The Child in America (1928), p.572","url":"https://archive.org/details/childinamerica00thom/page/572/mode/2up"}],"status":"書誌確認済み","note":"原著の命題。心理的な願望実現の法則と混同しない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_999","title":"象徴的相互作用論","summary":"人は物事がもつ意味に基づいて行動し、その意味は他者との相互作用や解釈を通して作られ、変わると捉える立場。会議での沈黙が、ある職場では同意、別の職場では慎重な検討と理解されることなどが例になる。行き違いを考える際、行動だけでなく当事者がそこに与えた意味を確かめる視点になる。すべての意味が自由に選べるわけではなく、制度や力関係の影響もある。個別の心理効果や会話の手順ではなく、社会を理解する理論的視角である。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":38,"display_id":336,"aliases":["symbolic interactionism"],"related_theory_ids":["kb_434","kb_111","kb_942"],"canonical_id":"kb_999","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Herbert Blumer","works":["Symbolic Interactionism: Perspective and Method (1969)"],"sources":[{"title":"Symbolic Interactionism: Perspective and Method (1969)","url":"https://www.ucpress.edu/books/symbolic-interactionism/paper"}],"status":"書誌確認済み","note":"意味、社会的相互作用、解釈という三つの前提を中心に説明。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1000","title":"社会的表象理論","summary":"集団の中で共有される知識やイメージが、身近でない事象を理解し、語り、行動する枠組みになると捉える理論。新しい技術が「便利な道具」や「脅威」として日常会話に取り込まれていく過程などを考える。言葉を伝えるときは、相手の集団でその対象がどう理解されているかを確かめる手掛かりになる。全員が同じ意見をもつという意味ではなく、表象は対話や対立を通して変わる。多数派への同調や単なるステレオタイプとは説明対象が異なる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":39,"display_id":337,"aliases":["social representations theory"],"related_theory_ids":["kb_455","kb_927","kb_942"],"canonical_id":"kb_1000","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Serge Moscovici；Gordon Sammutほか編（参照資料）","works":["The Cambridge Handbook of Social Representations (2015)"],"sources":[{"title":"The Cambridge Handbook of Social Representations (2015)","url":"https://assets.cambridge.org/97811070/42001/excerpt/9781107042001_excerpt.pdf"}],"status":"書誌確認済み","note":"日常知識の社会的生成という射程。個別効果の強さを保証しない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1001","title":"道徳的パニック","summary":"ある人々や出来事が社会の価値を脅かすものとして描かれ、報道や社会的反応によって懸念や統制要求が急激に高まる過程を捉える社会学的概念。少数の事例から特定集団全体が危険だと語られる場合などを分析できる。情報を読む際は、実際の発生頻度、被害、報道の規模を別々に確認する。懸念の存在だけで「パニック」と決めつけず、反応が不釣り合いかを資料で検討する必要がある。実在する被害を否定するための言葉ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":40,"display_id":338,"aliases":["moral panic","モラル・パニック"],"related_theory_ids":["kb_106","kb_597","kb_927"],"canonical_id":"kb_1001","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Stanley Cohen","works":["Folk Devils and Moral Panics (1972；参照版)"],"sources":[{"title":"Folk Devils and Moral Panics (1972；参照版)","url":"https://www.routledge.com/Folk-Devils-and-Moral-Panics-1st-Edition/Cohen/p/book/9780415610162"}],"status":"書誌確認済み","note":"社会的反応を分析する概念。誰かの不安を病理化する名称ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1002","title":"他者化","summary":"ある人々を「私たち」とは本質的に異なる存在として描き、所属や権利、共感の範囲から外す過程。所属部署や出自の違いから「彼らは分かり合えない」と一括りにすると、個々の事情を聞く機会が失われる。対話では集団名による説明と、実際の行為や必要を分けて確かめる視点になる。単に違いを認めることや個人的に距離を置くことのすべてを指すわけではない。制度、権力、資源配分も含む概念であり、個人の好悪だけでは説明できない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":41,"display_id":339,"aliases":["othering"],"related_theory_ids":["kb_058","kb_485","kb_470"],"canonical_id":"kb_1002","legacy_ids":[],"knowledge_type":"thought","provenance":{"attribution":"john a. powell / Stephen Menendian","works":["The Problem of Othering: Towards Inclusiveness and Belonging (2016)"],"sources":[{"title":"The Problem of Othering: Towards Inclusiveness and Belonging (2016)","url":"https://www.otheringandbelonging.org/wp-content/uploads/2016/07/OtheringAndBelonging_Issue1.pdf"}],"status":"書誌確認済み","note":"確立した批判的・社会的概念として収録。独立した実験効果という名称を付けない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1003","title":"共有現実理論","summary":"ある対象について、自分と他者の内的な理解や感情が共通していると感じる経験に注目する理論。出来事を話し「同じように見ていた」と感じることで、自分の解釈への確信が支えられる場合などがある。対話では結論だけでなく、どの意味や感情を共有したのかを確かめる視点になる。表面的に同じ発言をしただけでは共有現実とは限らず、共感や共通知識とも区別される。共有によって判断が正確になる保証はなく、偏った理解が強まる場合も考慮する。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":42,"display_id":340,"aliases":["shared reality theory"],"related_theory_ids":["kb_707","kb_266","kb_404"],"canonical_id":"kb_1003","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Gerald Echterhoff / E. Tory Higgins / John M. Levine","works":["Shared Reality: Experiencing Commonality With Others’ Inner States About the World (2009)"],"sources":[{"title":"Shared Reality: Experiencing Commonality With Others’ Inner States About the World (2009)","url":"https://pubmed.ncbi.nlm.nih.gov/26162223/"}],"status":"書誌確認済み","note":"対象についての内的状態の共通性。単なる意見一致から区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1004","title":"相互独立的・相互協調的自己観","summary":"自己を他者から区切られた独立した存在として捉える見方と、関係や役割の中で捉える見方を比較する枠組み。意思表示を「自分の希望を伝えること」と捉えるか、「関係の調整」と捉えるかで、同じ言動の意味が変わる場合がある。文化や職場の違いを理解するとき、自分の当然を点検する手掛かりになる。国籍で人を二分したり、一方が成熟していると評価したりしない。同じ人でも関係や場面によって、両方の見方を使いうる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":43,"display_id":341,"aliases":["independent and interdependent self-construals"],"related_theory_ids":["kb_058","kb_258","kb_456"],"canonical_id":"kb_1004","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Hazel R. Markus / Shinobu Kitayama","works":["Culture and the self (1991)"],"sources":[{"title":"Culture and the self (1991)","url":"https://doi.org/10.1037/0033-295X.98.2.224"}],"status":"書誌確認済み","note":"文化的な自己の構成。単純な東西二分や性格診断にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1005","title":"自己評価維持モデル","summary":"身近な人の優れた成果が自分の評価に及ぼす影響を、心理的な近さ、成績の差、その領域の自己にとっての重要性から説明するモデル。親友の得意分野を誇らしく感じても、自分の大切な仕事で追い抜かれると脅威を感じることがある。嫉妬や応援が入り交じるとき、相手への好悪だけでなく比較の領域を見直す手掛かりになる。近い人の成功を必ず妬むという法則ではない。関係や自己評価を調整する方法には個人差や状況差がある。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":44,"display_id":342,"aliases":["self-evaluation maintenance model"],"related_theory_ids":["kb_266","kb_122","kb_396"],"canonical_id":"kb_1005","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: self-evaluation-maintenance-model"],"sources":[{"title":"APA Dictionary of Psychology: self-evaluation-maintenance-model","url":"https://dictionary.apa.org/self-evaluation-maintenance-model"}],"status":"書誌確認済み","note":"Abraham Tesserら。反映過程と比較過程を区別する。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1006","title":"社会的役割理論","summary":"性別などによる行動の違いや類似を、社会で担う役割と、その役割への期待から説明する理論。特定の人々がケアや指揮を多く担当すると、その行動が生来の性質だと見られ、役割分担が再生産される場合がある。人材配置では、観察された行動と与えられてきた機会を分けて考える。すべての差を役割だけに還元するものではなく、生物的条件と社会構造の関係も検討する。既存の役割に従うべきだという規範ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-v","taxonomy_order":45,"display_id":343,"aliases":["social role theory"],"related_theory_ids":["kb_927","kb_939","kb_075"],"canonical_id":"kb_1006","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Alice H. Eagly / Wendy Wood","works":["Social Role Theory（著者による章）"],"sources":[{"title":"Social Role Theory（著者による章）","url":"https://doi.org/10.4135/9781446249222.n49"}],"status":"書誌確認済み","note":"Eaglyらの社会的役割理論。一般的な役割理論全体とは区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_017","taxonomy_order":1,"display_id":344,"aliases":[],"related_theory_ids":["kb_870","kb_872","kb_873","kb_874","kb_968","kb_970"]},{"id":"kb_870","taxonomy_order":2,"display_id":345,"aliases":["Stroop effect"],"related_theory_ids":["kb_493","kb_017"]},{"id":"kb_872","taxonomy_order":3,"display_id":346,"aliases":["inattentional blindness","不注意盲"],"related_theory_ids":["kb_017","kb_493","kb_874","kb_873","kb_968","kb_969","kb_970"]},{"id":"kb_873","taxonomy_order":4,"display_id":347,"aliases":["change blindness","変化盲目"],"related_theory_ids":["kb_017","kb_745","kb_872"]},{"id":"kb_874","taxonomy_order":5,"display_id":348,"aliases":["attentional blink","アテンショナル・ブリンク"],"related_theory_ids":["kb_017","kb_745","kb_872","kb_970"]},{"id":"kb_745","taxonomy_order":6,"display_id":349,"aliases":["working memory model","作業記憶モデル","中央実行系"],"related_theory_ids":["kb_493","kb_873","kb_874","kb_903","kb_746","kb_965","kb_981","kb_1012"]},{"id":"kb_738","taxonomy_order":7,"display_id":350,"aliases":["Ebbinghaus forgetting curve","忘却曲線"],"related_theory_ids":["kb_200","kb_199","kb_879","kb_975"]},{"id":"kb_879","taxonomy_order":8,"display_id":351,"aliases":["retrieval-induced forgetting","想起誘導性忘却"],"related_theory_ids":["kb_738","kb_199","kb_975"]},{"id":"kb_739","taxonomy_order":9,"display_id":352,"aliases":["serial position effect","初頭・新近性効果"],"related_theory_ids":["kb_740","kb_002","kb_001"]},{"id":"kb_744","taxonomy_order":10,"display_id":353,"aliases":["levels of processing framework","処理水準モデル"],"related_theory_ids":["kb_415","kb_748","kb_830","kb_1076"]},{"id":"kb_743","taxonomy_order":11,"display_id":354,"aliases":["encoding specificity principle","符号化特定性"],"related_theory_ids":["kb_742","kb_830","kb_826","kb_827","kb_1078"]},{"id":"kb_876","taxonomy_order":12,"display_id":355,"aliases":["misinformation effect","事後情報効果"],"related_theory_ids":["kb_831","kb_718","kb_877","kb_973","kb_977","kb_979"]},{"id":"kb_877","taxonomy_order":13,"display_id":356,"aliases":["source monitoring","情報源モニタリング"],"related_theory_ids":["kb_831","kb_858","kb_876","kb_976","kb_977","kb_979"]},{"id":"kb_826","taxonomy_order":14,"display_id":357,"aliases":["context-dependent memory","文脈依存効果"],"related_theory_ids":["kb_827","kb_743","kb_980"]},{"id":"kb_827","taxonomy_order":15,"display_id":358,"aliases":["state-dependent memory","状態依存学習"],"related_theory_ids":["kb_826","kb_878","kb_743"]},{"id":"kb_878","taxonomy_order":16,"display_id":359,"aliases":["mood-congruent memory","気分一致効果"],"related_theory_ids":["kb_827","kb_511","kb_980"]},{"id":"kb_742","taxonomy_order":17,"display_id":360,"aliases":["dual coding theory","デュアルコーディング"],"related_theory_ids":["kb_743","kb_493","kb_971","kb_1078"]},{"id":"kb_746","taxonomy_order":18,"display_id":361,"aliases":["chunking","チャンキング","情報のまとまり化"],"related_theory_ids":["kb_825","kb_745","kb_962","kb_1079"]},{"id":"kb_441","taxonomy_order":19,"display_id":362,"aliases":[],"related_theory_ids":["kb_974","kb_1073"]},{"id":"kb_831","taxonomy_order":20,"display_id":363,"aliases":["memory reconsolidation","記憶再固定化"],"related_theory_ids":["kb_440","kb_199","kb_876","kb_877","kb_919","kb_921","kb_979"]},{"id":"kb_393","taxonomy_order":21,"display_id":364,"aliases":[],"related_theory_ids":[]},{"id":"kb_741","taxonomy_order":22,"display_id":365,"aliases":["generation effect","自己生成効果"],"related_theory_ids":["kb_199","kb_748","kb_828"]},{"id":"kb_830","taxonomy_order":23,"display_id":366,"aliases":["transfer-appropriate processing","転移適切処理"],"related_theory_ids":["kb_744","kb_743"]},{"id":"kb_493","taxonomy_order":24,"display_id":367,"aliases":[],"related_theory_ids":["kb_737","kb_742","kb_745","kb_840","kb_870","kb_872","kb_903","kb_577","kb_965","kb_967"]},{"id":"kb_740","taxonomy_order":25,"display_id":368,"aliases":["Von Restorff effect","isolation effect","孤立効果"],"related_theory_ids":["kb_550","kb_739"]},{"id":"kb_829","taxonomy_order":26,"display_id":369,"aliases":["illusion of fluency","fluency illusion","流暢性バイアス"],"related_theory_ids":["kb_718","kb_896","kb_199"]},{"id":"kb_414","taxonomy_order":27,"display_id":370,"aliases":[],"related_theory_ids":["kb_858","kb_918","kb_972","kb_973","kb_976","kb_1079"]},{"id":"kb_531","taxonomy_order":28,"display_id":371,"aliases":[],"related_theory_ids":["kb_967","kb_1073"]},{"id":"kb_965","title":"注意資源理論","summary":"複数の課題が限られた処理資源を分け合うため、同時に求められる処理量が増えると成績が下がりうるという説明。難しい文章を読みながら込み入った会話をすると、どちらかの内容を落としやすい。仕事では同時進行を当然視せず、集中を必要とする時間を分ける設計に役立つ。練習で自動化された処理や、異なる種類の資源を使う課題もあるため、すべての組合せが同じ程度に干渉するとは限らない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":29,"display_id":372,"aliases":["capacity theory of attention","注意容量理論"],"related_theory_ids":["kb_493","kb_745"],"canonical_id":"kb_965","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Daniel Kahneman","works":["Attention and Effort (1973)"],"sources":[{"title":"Attention and Effort (1973)","url":"https://kahneman.scholar.princeton.edu/document/4"}],"status":"書誌確認済み","note":"単一資源説と複数資源説を混同せず、容量という説明の水準を示す。"},"quotation":null,"access_tier":"complete"},{"id":"kb_967","title":"注意残余","summary":"ある仕事から別の仕事へ移っても、直前の仕事への思考が残り、新しい仕事に注意を十分向けにくくなる現象。未完の企画を中断して会議に入ると、会議中も企画の続きが気になることが例になる。切り替え前に次に行うことを短く記録し、区切りを設けるなど、移行を設計する手掛かりになる。単に切り替えに時間がかかる現象や未完了課題の記憶優位とは焦点が異なり、残余の程度は課題や中断条件で変わる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":30,"display_id":373,"aliases":["attention residue"],"related_theory_ids":["kb_531","kb_493"],"canonical_id":"kb_967","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Sophie Leroy","works":["Why is it so hard to do my work? (2009)"],"sources":[{"title":"Why is it so hard to do my work? (2009)","url":"https://doi.org/10.1016/j.obhdp.2009.04.002"}],"status":"書誌確認済み","note":"注意残余と一般的なマルチタスクのコストを同一視しない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_968","title":"注意の捕捉","summary":"現在行っている課題とは別の刺激に注意が引き寄せられる現象。読書中に突然の通知音へ目を向けるように、刺激の目立ちやすさや、自分の目標に合う特徴が関わる。集中したい場面では不要な通知を減らし、必要な警告は適切に目立たせる設計に使える。ただし目立つ物なら何でも必ず注意を奪うわけではない。注意を向ける準備、課題の負荷、学習した価値によって捕捉されやすさが変わる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":31,"display_id":374,"aliases":["attentional capture","注意捕捉"],"related_theory_ids":["kb_017","kb_872"],"canonical_id":"kb_968","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: attentional-capture"],"sources":[{"title":"APA Dictionary of Psychology: attentional-capture","url":"https://dictionary.apa.org/attentional-capture"}],"status":"書誌確認済み","note":"外因的刺激と目標による制御の関係は研究上の論点。"},"quotation":null,"access_tier":"complete"},{"id":"kb_970","title":"選択的注意","summary":"同時に入る多くの情報のうち、目的に関係する対象を優先して処理する働き。騒がしい場所で相手の話へ注意を向けると、周囲の会話の内容は把握しにくくなる。会議や学習では注目すべき対象を明確にし、重要な情報が見落とされる可能性も見込んで確認を設ける。選択されなかった情報がすべて処理されないという意味ではない。注意の選択は、刺激、目標、慣れ、負荷に応じて変わる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":32,"display_id":375,"aliases":["selective attention"],"related_theory_ids":["kb_017","kb_872","kb_874"],"canonical_id":"kb_970","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: attention"],"sources":[{"title":"APA Dictionary of Psychology: attention","url":"https://dictionary.apa.org/attention"}],"status":"書誌確認済み","note":"注意の一般的な選択機能。非注意性盲目はその結果生じうる個別現象として区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_972","title":"スキーマ理論","summary":"経験から作られた知識の枠組みが、新しい情報の理解、記憶、推測を方向づけるという考え方。会議と聞けば議題や発言順を予想できるが、実際にはなかった内容まで補って思い出すこともある。学習では既に知る構造に新しい知識を結びつけ、同時にその枠に合わない事実を確かめる視点になる。知識の構造を扱う概念であり、連想の一時的な活性化を説明するプライミングや、信念を守る確証バイアスと同義ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":33,"display_id":376,"aliases":["schema theory"],"related_theory_ids":["kb_414","kb_596","kb_858","kb_973"],"canonical_id":"kb_972","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: schema"],"sources":[{"title":"APA Dictionary of Psychology: schema","url":"https://dictionary.apa.org/schema"}],"status":"書誌確認済み","note":"Bartlett、Piagetらに連なる複数の用法。単一提唱者の万能理論にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_973","title":"スクリプト理論","summary":"よく経験する出来事の典型的な順序が、ひとまとまりの知識として理解や記憶を助けるという説明。飲食店で入店、注文、食事、支払いを予測できるのが例になる。初めての業務の手順を伝えるときは、相手が前提としている順序を確かめると行き違いを減らせる。実際の出来事が典型と異なると、抜けた工程を勝手に補う場合もある。一般的なスキーマのうち出来事の系列に焦点を当て、台本の読み上げ技法とは区別する。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":34,"display_id":377,"aliases":["script theory","スクリプト・スキーマ"],"related_theory_ids":["kb_414","kb_876","kb_972"],"canonical_id":"kb_973","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: script"],"sources":[{"title":"APA Dictionary of Psychology: script","url":"https://dictionary.apa.org/script"}],"status":"書誌確認済み","note":"SchankとAbelsonの出来事知識に対応する用法。"},"quotation":null,"access_tier":"complete"},{"id":"kb_974","title":"展望記憶","summary":"将来の適切な時点で、予定していた行動を思い出して実行するための記憶。午後3時に連絡する時間ベースの予定と、相手に会ったら資料を渡す出来事ベースの予定などがある。予定を覚えているだけでは足りず、別の活動中に実行のきっかけを検出する必要がある。仕事では通知や物の配置を具体的な行動に結び付けるとよい。過去を思い出す記憶や、将来を想像することとは異なり、失敗を意欲不足だけで説明しない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":35,"display_id":378,"aliases":["prospective memory","未来記憶"],"related_theory_ids":["kb_172","kb_441"],"canonical_id":"kb_974","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: prospective-memory"],"sources":[{"title":"APA Dictionary of Psychology: prospective-memory","url":"https://dictionary.apa.org/prospective-memory"}],"status":"書誌確認済み","note":"実行意図は展望記憶を支援する手法であり、同義ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_975","title":"前向干渉・逆向干渉","summary":"似た内容の記憶同士が競合し、学習や想起を妨げる現象。古い暗証番号が新しい番号の想起を邪魔するのが前向干渉、新しい番号の学習で古い番号を思い出しにくくなるのが逆向干渉である。似た手順を覚える際は、違いを明示し、適切な状況で取り出す練習を設ける。単に時間が経ったための忘却とは区別する。二方向を比較する一つのカードとし、どの記憶が必ず消えるかを予測する法則にはしない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":36,"display_id":379,"aliases":["proactive and retroactive interference"],"related_theory_ids":["kb_738","kb_879"],"canonical_id":"kb_975","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: interference"],"sources":[{"title":"APA Dictionary of Psychology: interference","url":"https://dictionary.apa.org/interference"}],"status":"書誌確認済み","note":"片方向の名称は全体の同義語ではなく関連検索語。"},"quotation":null,"access_tier":"complete"},{"id":"kb_976","title":"舌先現象","summary":"知っている語や名前を思い出せそうだと感じながら、今はうまく取り出せない状態。人物の職業や名前の頭文字は浮かぶのに、名前全体が出てこないことが例になる。情報が失われた場合と、一時的な検索の失敗を分けて考える手掛かりになる。少し時間を置く、関連する文脈を確かめるなどで思い出すこともあるが、必ず解決する方法ではない。日常で時々起きる現象だけを根拠に、認知機能の病気や知識不足を判断しない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":37,"display_id":380,"aliases":["tip-of-the-tongue phenomenon","舌端現象"],"related_theory_ids":["kb_877","kb_414"],"canonical_id":"kb_976","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: tip-of-the-tongue-phenomenon"],"sources":[{"title":"APA Dictionary of Psychology: tip-of-the-tongue-phenomenon","url":"https://dictionary.apa.org/tip-of-the-tongue-phenomenon"}],"status":"書誌確認済み","note":"TOTは短い略称なので補助語へ。"},"quotation":null,"access_tier":"complete"},{"id":"kb_977","title":"フラッシュバルブ記憶","summary":"驚きや重大さを伴う出来事の知らせを受けた状況について、鮮明に覚えていると感じる記憶。大きな出来事をどこで誰から聞いたかが詳しく浮かぶことなどが例になる。鮮明さや確信は正確さと同じではなく、後の情報や反復によって内容が変わる場合もある。証言や会話では「はっきり覚えている」という感覚だけで確認を省かず、記録と照らす。写真のような完全保存を意味せず、すべての強い記憶がこの種類になるわけでもない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":38,"display_id":381,"aliases":["flashbulb memory"],"related_theory_ids":["kb_876","kb_877"],"canonical_id":"kb_977","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"American Psychological Association","works":["APA Dictionary of Psychology: flashbulb-memory"],"sources":[{"title":"APA Dictionary of Psychology: flashbulb-memory","url":"https://dictionary.apa.org/flashbulb-memory"}],"status":"書誌確認済み","note":"BrownとKulikの研究に由来。鮮明さと保持精度を明確に分離。"},"quotation":null,"access_tier":"complete"},{"id":"kb_978","title":"回想バンプ","summary":"中高年以降に人生を振り返った際、青年期から成人初期の出来事が相対的に多く想起される傾向。昔の友人との出会いや進学の記憶が、他の時期より多く浮かぶことなどが例になる。人生の語りや世代間の対話では、思い出されやすさと当時の出来事の客観的重要性を分けて考えられる。山が現れる年齢や大きさは、質問、手掛かり、文化などで変わる。人生の最良期が若い時期に固定されるという主張ではない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":39,"display_id":382,"aliases":["reminiscence bump"],"related_theory_ids":["kb_246","kb_909"],"canonical_id":"kb_978","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"David C. Rubin / Matthew D. Schulkind","works":["The distribution of autobiographical memories across the lifespan (1997)"],"sources":[{"title":"The distribution of autobiographical memories across the lifespan (1997)","url":"https://pubmed.ncbi.nlm.nih.gov/9421572/"}],"status":"書誌確認済み","note":"人生全体にわたる想起分布の研究。単なる懐古や初頭効果とは区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_979","title":"偽記憶","summary":"実際には起きなかった出来事を覚えていると感じたり、起きた出来事を実際と異なる形で思い出したりすること。会話で聞いた内容を、自分が直接見たこととして思い出す場合などがある。記憶は再構成されるため、誤情報、連想、出所の取り違えなど複数の経路が関わる。聞き取りでは誘導的な質問を避け、独立した記録を照合する。記憶違いと意図的な嘘は別であり、この概念だけで個別の記憶が真か偽かを決められない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":40,"display_id":383,"aliases":["false memory","虚記憶"],"related_theory_ids":["kb_876","kb_877","kb_831"],"canonical_id":"kb_979","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"OpenStax / Rose M. Spielmanほか","works":["Psychology 2e, 8.3 Problems with Memory"],"sources":[{"title":"Psychology 2e, 8.3 Problems with Memory","url":"https://openstax.org/books/psychology-2e/pages/8-3-problems-with-memory"}],"status":"書誌確認済み","note":"誤情報効果は生成経路の一つ。偽記憶はより広い現象で別カード。"},"quotation":null,"access_tier":"complete"},{"id":"kb_980","title":"プルースト効果","summary":"においが、個人的な過去の出来事と当時の感情を呼び起こす現象を指す通称。昔使った石けんの香りから、家族との生活場面が急に浮かぶような例で理解できる。においと言葉や写真では、想起される記憶の感情的性質が異なる場合がある。思い出を語るきっかけにはなるが、香りが誰にでも良い記憶を作る、記憶を正確に復元するという効果ではない。不快な経験を思い出す人もいるため、利用時は本人の反応を優先する。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-m","taxonomy_order":41,"display_id":384,"aliases":["Proust phenomenon","Proust effect","嗅覚誘発自伝的記憶"],"related_theory_ids":["kb_826","kb_878"],"canonical_id":"kb_980","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Rachel S. Herz / Jonathan W. Schooler","works":["A naturalistic study of autobiographical memories evoked by olfactory and visual cues (2002)"],"sources":[{"title":"A naturalistic study of autobiographical memories evoked by olfactory and visual cues (2002)","url":"https://pubmed.ncbi.nlm.nih.gov/11868193/"}],"status":"書誌確認済み","note":"嗅覚で誘発される自伝的記憶に限定。医療上の改善効果は主張しない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_902","taxonomy_order":1,"display_id":385,"aliases":["Erikson psychosocial development theory","心理社会的発達段階説"],"related_theory_ids":["kb_246","kb_589","kb_251","kb_909","kb_910","kb_913"]},{"id":"kb_903","taxonomy_order":2,"display_id":386,"aliases":["Piaget theory of cognitive development","ピアジェ理論"],"related_theory_ids":["kb_745","kb_493","kb_914","kb_920","kb_904","kb_1009"]},{"id":"kb_904","taxonomy_order":3,"display_id":387,"aliases":["zone of proximal development","ZPD","発達の最近接領域"],"related_theory_ids":["kb_169","kb_828","kb_903","kb_948"]},{"id":"kb_909","taxonomy_order":4,"display_id":388,"aliases":["social clock","ソーシャル・クロック","社会時計"],"related_theory_ids":["kb_266","kb_902","kb_913","kb_915","kb_978"]},{"id":"kb_910","taxonomy_order":5,"display_id":389,"aliases":["life-span developmental psychology","ライフスパン発達心理学"],"related_theory_ids":["kb_902","kb_916","kb_917","kb_912","kb_951","kb_911"]},{"id":"kb_911","taxonomy_order":6,"display_id":390,"aliases":["SOCモデル","selective optimization with compensation"],"related_theory_ids":["kb_572","kb_569","kb_910"]},{"id":"kb_912","taxonomy_order":7,"display_id":391,"aliases":["socioemotional selectivity theory","SST","社会情緒的選択性理論"],"related_theory_ids":["kb_753","kb_562","kb_910"]},{"id":"kb_913","taxonomy_order":8,"display_id":392,"aliases":["emerging adulthood","エマージング・アダルトフッド"],"related_theory_ids":["kb_256","kb_589","kb_902","kb_909","theory-ba3eb39f-7dd4-4795-8eb0-c17c2b34fd1e"]},{"id":"kb_914","taxonomy_order":9,"display_id":393,"aliases":["ecological systems theory","ブロンフェンブレンナーの生態学的理論"],"related_theory_ids":["kb_559","kb_903","kb_915","kb_920","kb_1010"]},{"id":"kb_915","taxonomy_order":10,"display_id":394,"aliases":["life course theory","ライフコース・アプローチ"],"related_theory_ids":["kb_288","kb_914","kb_909"]},{"id":"kb_916","taxonomy_order":11,"display_id":395,"aliases":["fluid and crystallized intelligence","流動性知能","結晶性知能","Gf・Gc"],"related_theory_ids":["kb_910","kb_825","kb_724"]},{"id":"kb_1009","title":"コールバーグの道徳性発達理論","summary":"道徳判断を、どの結論を選ぶかだけでなく、その理由づけの発達から捉える段階理論。罰を避けるため、周囲に認められるため、原則を守るためなど、同じ行為でも説明の根拠は異なる。意見の違いを話し合う際、何を理由に判断したのかを聞く視点になる。実際の行動の善悪や人間の価値を段階で採点するものではない。文化、ジェンダー、課題の作り方、理由づけと実行の差に関する批判があり、固定した普遍的診断にはしない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-life","taxonomy_order":12,"display_id":396,"aliases":["Kohlberg''s theory of moral development"],"related_theory_ids":["kb_903","kb_954","kb_955"],"canonical_id":"kb_1009","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Lawrence Kohlberg；OpenStax（参照教材）","works":["Psychology 2e, 9.2 Lifespan Theories"],"sources":[{"title":"Psychology 2e, 9.2 Lifespan Theories","url":"https://openstax.org/books/psychology-2e/pages/9-2-lifespan-theories"}],"status":"書誌確認済み","note":"道徳的推論の歴史的発達モデル。規範的な人物ランキングではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1010","title":"気質理論","summary":"早期から見られる反応の強さや注意、自己調整などの個人差を、生物的基盤と発達・環境の相互作用から捉える理論群。新しい場所へすぐ近づく子と、様子を見てから参加する子では、安心して試せる支援も違う。本人を怠惰やわがままと決めず、反応の特徴と環境の合い方を見る手掛かりになる。気質は将来の性格や成功を固定しない。ThomasとChess、Rothbartらでモデルが異なり、特定の類型をすべての人へ当てはめない。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-life","taxonomy_order":13,"display_id":397,"aliases":["temperament theory"],"related_theory_ids":["kb_724","kb_914","kb_920"],"canonical_id":"kb_1010","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Mary K. Rothbart / Stephan A. Ahadi / David E. Evans","works":["Temperament and personality: origins and outcomes (2000)"],"sources":[{"title":"Temperament and personality: origins and outcomes (2000)","url":"https://pubmed.ncbi.nlm.nih.gov/10653510/"}],"status":"書誌確認済み","note":"気質の反応性・調整と発達を扱い、成人性格との同一視を避ける。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1011","title":"遅延満足","summary":"目の前の小さな報酬をすぐ受け取る代わりに、後のより大きな報酬を待つこと。今遊ぶ代わりに、準備を終えてから長く遊ぶような場面で考えられる。待てるかどうかは注意の向け方だけでなく、約束が守られる見込みや家庭・生活の条件にも左右される。実践では誘惑を見えにくくし、待つ理由と予定を明確にする。幼少期の一つの課題だけで人生の成功が決まるという解釈は不適切で、後の成績との関連には背景要因を考慮する必要がある。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-life","taxonomy_order":14,"display_id":398,"aliases":["delay of gratification","満足遅延"],"related_theory_ids":["kb_175","kb_176","kb_174"],"canonical_id":"kb_1011","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Walter Mischelら；Tyler W. Watts / Greg J. Duncan / Haonan Quan（再検討）","works":["Revisiting the Marshmallow Test (2018)"],"sources":[{"title":"Revisiting the Marshmallow Test (2018)","url":"https://pubmed.ncbi.nlm.nih.gov/29799765/"}],"status":"書誌確認済み","note":"マシュマロ実験の課題名は補助語。待つ力と将来結果の因果を断定しない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_917","taxonomy_order":1,"display_id":399,"aliases":["神経可塑性","脳可塑性","neuroplasticity","brain plasticity"],"related_theory_ids":["kb_263","kb_198","kb_918","kb_920","kb_921","kb_910","kb_919"]},{"id":"kb_918","taxonomy_order":2,"display_id":400,"aliases":["Hebbian learning","Hebbの法則","ヘッブ学習"],"related_theory_ids":["kb_917","kb_414","kb_919"]},{"id":"kb_919","taxonomy_order":3,"display_id":401,"aliases":["long-term potentiation","LTP","シナプス長期増強"],"related_theory_ids":["kb_831","kb_917","kb_918"]},{"id":"kb_920","taxonomy_order":4,"display_id":402,"aliases":["sensitive period","感受性期"],"related_theory_ids":["kb_917","kb_903","kb_914","kb_1010"]},{"id":"kb_921","taxonomy_order":5,"display_id":403,"aliases":["sleep-dependent memory consolidation","睡眠依存性記憶固定"],"related_theory_ids":["kb_831","kb_200","kb_917","kb_540"]},{"id":"kb_922","taxonomy_order":6,"display_id":404,"aliases":["allostatic load","アロスタシス負荷","アロスタティック・ロード"],"related_theory_ids":["kb_228","kb_763","kb_540","kb_940","kb_946"]},{"id":"kb_1012","title":"実行機能","summary":"目標に沿って思考や行動を調整するための機能群。抑制、作業記憶、認知的柔軟性などを含み、必要な情報を保ちながら不要な反応を抑え、状況に応じて切り替える働きとして説明される。作業を小分けにし、手順を外に書くことは負荷を軽くする助けになる。計画が進まない理由を意志の弱さだけに求めない視点になるが、単一の能力や診断ではない。睡眠、ストレス、課題、発達段階などでも発揮のされ方が変わる。","category_id":"psychology","category_title":"心理学","subcategory_id":"psychology-n","taxonomy_order":7,"display_id":405,"aliases":["executive functions","executive function"],"related_theory_ids":["kb_745","kb_574","kb_577"],"canonical_id":"kb_1012","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Adele Diamond","works":["Executive functions (2013)"],"sources":[{"title":"Executive functions (2013)","url":"https://pubmed.ncbi.nlm.nih.gov/23020641/"}],"status":"書誌確認済み","note":"複数の中核機能からなる枠組み。自己制御一般と完全同義にはしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_754","taxonomy_order":1,"display_id":1,"aliases":["bounded rationality","制約された合理性"],"related_theory_ids":["kb_277","kb_191","kb_981","kb_1039","kb_1040","kb_1041","kb_1044"]},{"id":"kb_756","taxonomy_order":2,"display_id":2,"aliases":["expected utility theory","EUT","期待効用"],"related_theory_ids":["kb_755","kb_758","kb_835","kb_133","kb_1017","kb_1061"]},{"id":"kb_755","taxonomy_order":3,"display_id":3,"aliases":["expected value","期待価値","数学的期待値"],"related_theory_ids":["kb_756","kb_955","kb_1015","kb_1025"]},{"id":"kb_133","taxonomy_order":4,"display_id":4,"aliases":["反射効果","reflection effect"],"related_theory_ids":["kb_134","kb_759","kb_137","kb_756"]},{"id":"kb_887","taxonomy_order":5,"display_id":5,"aliases":["s