013","kb_1014","kb_1017","kb_1019","kb_1020"]},{"id":"kb_140","taxonomy_order":34,"display_id":34,"aliases":["decoy effect"],"related_theory_ids":[]},{"id":"kb_141","taxonomy_order":35,"display_id":35,"aliases":["compromise effect"],"related_theory_ids":["kb_953","theory-1789620805420-wbuepmtu"]},{"id":"kb_136","taxonomy_order":36,"display_id":36,"aliases":["status quo bias"],"related_theory_ids":["kb_807","kb_808"]},{"id":"kb_135","taxonomy_order":37,"display_id":37,"aliases":["endowment effect"],"related_theory_ids":["kb_837","kb_838","kb_846"]},{"id":"kb_759","taxonomy_order":38,"display_id":38,"aliases":["certainty effect","確実性バイアス"],"related_theory_ids":["kb_809","kb_760","kb_835","kb_133"]},{"id":"kb_837","taxonomy_order":39,"display_id":39,"aliases":["IKEA effect","イケア効果"],"related_theory_ids":["kb_273","kb_135"]},{"id":"kb_514","taxonomy_order":40,"display_id":40,"aliases":[],"related_theory_ids":["kb_1021","kb_1022"]},{"id":"kb_102","taxonomy_order":41,"display_id":41,"aliases":[],"related_theory_ids":[]},{"id":"kb_401","taxonomy_order":42,"display_id":42,"aliases":[],"related_theory_ids":["kb_959"]},{"id":"theory-1789620805420-wbuepmtu","taxonomy_order":43,"display_id":43,"aliases":["松竹梅の法則"],"related_theory_ids":["kb_141"]},{"id":"kb_761","taxonomy_order":44,"display_id":44,"aliases":["pain of paying","支払痛"],"related_theory_ids":["kb_757","kb_175","kb_1019","kb_1020"]},{"id":"kb_760","taxonomy_order":45,"display_id":45,"aliases":["zero-price effect","無料効果"],"related_theory_ids":["kb_759","kb_274"]},{"id":"kb_521","taxonomy_order":46,"display_id":46,"aliases":[],"related_theory_ids":["kb_897"]},{"id":"kb_897","taxonomy_order":47,"display_id":47,"aliases":["choice blindness","選択盲目"],"related_theory_ids":["kb_521","kb_420"]},{"id":"kb_275","taxonomy_order":48,"display_id":48,"aliases":[],"related_theory_ids":["kb_1041"]},{"id":"kb_139","taxonomy_order":49,"display_id":49,"aliases":[],"related_theory_ids":["kb_959","kb_1016"]},{"id":"kb_842","taxonomy_order":50,"display_id":50,"aliases":["unit bias","ユニット・バイアス"],"related_theory_ids":["kb_177","kb_138"]},{"id":"kb_838","taxonomy_order":51,"display_id":51,"aliases":["Diderot effect","ディドロ統一性"],"related_theory_ids":["kb_757","kb_135"]},{"id":"kb_1013","title":"左端数字効果","summary":"数値の左端の桁が変わると、実際の差以上に大きな違いとして受け止められることがある現象。例えば1,000円から999円への差を、同じ1円差の別の組合せより大きく感じる場合がある。価格を比べる際は、左端の印象だけでなく差額や総額を計算して確かめる。すべての端数価格が同じ効果をもつわけではなく、比較対象や注意の向け方で変わる。安さの印象を説明する概念であり、価格だけで品質や購入意向が決まるという法則ではない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":52,"display_id":52,"aliases":["left-digit effect"],"related_theory_ids":["kb_138","kb_137"],"canonical_id":"kb_1013","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Manoj Thomas / Vicki Morwitz","works":["Penny Wise and Pound Foolish: The Left-Digit Effect in Price Cognition (2005)"],"sources":[{"title":"Penny Wise and Pound Foolish: The Left-Digit Effect in Price Cognition (2005)","url":"https://doi.org/10.1086/429600"}],"status":"書誌確認済み","note":"数値認知の現象。9で終わる値付けのすべてと同義にはしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1014","title":"貨幣錯覚","summary":"お金の価値を判断する際、物価変動を考慮した実質額より、名目額に引きずられること。物価が給与より大きく上がっても、給与の数字が増えたため生活が豊かになったと感じる場合などがある。報酬や長期の計画を比べるとき、何がどれだけ買えるかという基準を併記する手掛かりになる。名目額を使うこと自体が誤りではなく、契約や制度には名目額が重要な場面もある。所得の変化への反応をすべて貨幣錯覚で説明しない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":53,"display_id":53,"aliases":["money illusion"],"related_theory_ids":["kb_137","kb_138"],"canonical_id":"kb_1014","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Eldar Shafir / Peter Diamond / Amos Tversky","works":["Money Illusion (1997)"],"sources":[{"title":"Money Illusion (1997)","url":"https://doi.org/10.1162/003355397555208"}],"status":"書誌確認済み","note":"名目と実質の区別。実質値の認識と公平感等の価値判断を分ける。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1015","title":"指数成長バイアス","summary":"一定割合で増える過程を、一定量ずつ増えるように捉え、将来の増加を過小評価する傾向。毎年同じ割合で増える量は元本や基数も変わるため、最初の増加額をそのまま年数倍した予想とは違ってくる。長期の費用や累積量を考える際は、直感だけでなく表や式で複数時点を確かめる。実際の成長がいつまでも同じ割合で続くという意味ではなく、上限や条件変化も別に検討する。計算の誤りと、予測モデル自体の誤りを分ける。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":54,"display_id":54,"aliases":["exponential growth bias"],"related_theory_ids":["kb_575","kb_755"],"canonical_id":"kb_1015","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Victor Stango / Jonathan Zinman","works":["Exponential Growth Bias and Household Finance (2009)"],"sources":[{"title":"Exponential Growth Bias and Household Finance (2009)","url":"https://doi.org/10.1111/j.1540-6261.2009.01518.x"}],"status":"書誌確認済み","note":"金融研究を起点とする数理的認識の傾向。個別の投資推奨ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1016","title":"顕著性バイアス","summary":"目立つ情報へ注意や重みが偏り、目立ちにくいが重要な情報が十分に考慮されない傾向。印象的な一件の苦情ばかりが会議で語られ、全体の発生率や利用者数が見落とされる場合などがある。判断では、目立つ理由と重要である理由を分け、共通の指標で候補を並べる。何が目立つかは比較状況や目的でも変わる。利用可能性ヒューリスティックと関わるが、思い出しやすさだけでなく、現在の比較で突出した属性に重みが付く点も扱う。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":55,"display_id":55,"aliases":["salience bias"],"related_theory_ids":["kb_597","kb_236","kb_139"],"canonical_id":"kb_1016","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Pedro Bordalo / Nicola Gennaioli / Andrei Shleifer","works":["Salience Theory of Choice Under Risk (2012)"],"sources":[{"title":"Salience Theory of Choice Under Risk (2012)","url":"https://scholar.harvard.edu/files/shleifer/files/salience_theory_of_choice_under_risk_qje.pdf"}],"status":"書誌確認済み","note":"顕著性の一般的な偏りと、引用した形式モデルの限定的予測を区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1017","title":"選好逆転","summary":"同じ選択肢でも、選ぶ、値段を付けるなどの評価方法によって好みの順位が逆になる現象。二つのくじのうち当たりやすい方を選ぶのに、売却価格は大きな賞金の方へ高く付ける場合などが例になる。選択の理由を確認するときは、質問形式や測り方が判断を変えていないかを点検する。新しい情報や価値観の変化による当然の好みの変化とは区別する。誰にも本当の好みがないという結論ではなく、引き出し方による不整合を扱う。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":56,"display_id":56,"aliases":["preference reversal"],"related_theory_ids":["kb_756","kb_137","kb_442"],"canonical_id":"kb_1017","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Sarah Lichtenstein / Paul Slovic","works":["Reversals of preference between bids and choices in gambling decisions (1971)"],"sources":[{"title":"Reversals of preference between bids and choices in gambling decisions (1971)","url":"https://doi.org/10.1037/h0031207"}],"status":"書誌確認済み","note":"選択と価格付けの比較。質問形式が同等かを確認する。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1018","title":"リスク感情理論","summary":"危険について考えた確率や結果の評価と、その瞬間に生じる恐怖や不安が食い違い、感情が行動を左右しうるという仮説。統計では低リスクと理解していても、鮮明な事故映像を見た直後は避けたくなる場合などがある。判断では計算した評価と現在の感情を別々に言葉にし、両方の情報を確かめる。感情を無視すべきという意味ではない。一般的な感情ヒューリスティックより、リスクに直面した感情と認知的評価の乖離に焦点を当てる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":57,"display_id":57,"aliases":["risk-as-feelings hypothesis","risk as feelings"],"related_theory_ids":["kb_430","kb_844","kb_887"],"canonical_id":"kb_1018","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"George Loewenstein / Elke U. Weber / Christopher K. Hsee / Ned Welch","works":["Risk as Feelings (2001)"],"sources":[{"title":"Risk as Feelings (2001)","url":"https://www.cmu.edu/dietrich/sds/docs/loewenstein/RiskAsFeelings.pdf"}],"status":"書誌確認済み","note":"仮説としての位置づけ。恐怖が常に非合理とはしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1019","title":"参照価格効果","summary":"提示価格を、過去の購入価格や通常価格などの比較基準に照らして評価すること。以前は高かったという表示を見ると、今の価格を割安に感じる場合などがある。買い物や見積もりの比較では、比較基準が実際の取引や必要に合っているかを確かめる。アンカリングと関連するが、価格の記憶や市場で形成した基準を含む。人によって参照価格は異なり、常に同じ値が保たれるわけではない。値引き率だけでなく支払総額と代替案を確認する。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":58,"display_id":58,"aliases":["reference price effect"],"related_theory_ids":["kb_138","kb_137","kb_761"],"canonical_id":"kb_1019","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Russell S. Winer","works":["A Reference Price Model of Brand Choice for Frequently Purchased Products (1986)"],"sources":[{"title":"A Reference Price Model of Brand Choice for Frequently Purchased Products (1986)","url":"https://doi.org/10.1086/209064"}],"status":"書誌確認済み","note":"日常的な価格判断の概念。参照点一般の正式別名にはしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1020","title":"分割価格効果","summary":"価格を本体代と手数料などに分けて示すことで、総額の認識や購入判断が変わること。安い本体価格に送料を別記すると、総額では高くても安い印象が残る場合がある。比較するときは、必要な追加費用を含む総額を同じ条件で並べる。分割表示が常に需要を増やすとは限らず、手数料の納得感や明示の仕方でも反応は変わる。支払いを複数回に分ける分割払いとは異なり、情報の示し方と処理の問題として捉える。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":59,"display_id":59,"aliases":["partitioned pricing"],"related_theory_ids":["kb_137","kb_761"],"canonical_id":"kb_1020","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Vicki G. Morwitz / Eric A. Greenleaf / Eric J. Johnson","works":["Divide and Prosper: Why Firms Divide Prices Instead of Charging a Single Price (1998)"],"sources":[{"title":"Divide and Prosper: Why Firms Divide Prices Instead of Charging a Single Price (1998)","url":"https://business.columbia.edu/faculty/research/divide-and-prosper-why-firms-divide-prices-instead-charging-single-price"}],"status":"書誌確認済み","note":"ドリップ価格は段階的開示を伴う別の側面。単純同義語にはしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1021","title":"スノッブ効果","summary":"他の人が多く持つことにより、その品の魅力や需要が下がること。珍しい品を選んだ人が、広く普及すると別の品へ移る場合などが例になる。他者との差別化が価値に含まれる選択を理解する手掛かりになる。希少な物を好む理由がすべてスノッブ効果とは限らず、実際の品質や利用価値も区別する。価格が高いこと自体を地位の表示として求めるヴェブレン効果や、流行に合わせるバンドワゴン効果とは説明する方向が異なる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":60,"display_id":60,"aliases":["snob effect"],"related_theory_ids":["kb_729","kb_514","kb_107","kb_1022"],"canonical_id":"kb_1021","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Harvey Leibenstein","works":["Bandwagon, Snob, and Veblen Effects in the Theory of Consumers’ Demand (1950)"],"sources":[{"title":"Bandwagon, Snob, and Veblen Effects in the Theory of Consumers’ Demand (1950)","url":"https://academic.oup.com/qje/article-abstract/64/2/183/1931945"}],"status":"書誌確認済み","note":"他者の消費量との関係を扱う需要の概念。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1022","title":"ヴェブレン効果","summary":"高い価格が地位や富の表示として価値をもち、価格の高さが需要を支えること。品質が同じでも、高価だと周囲に伝わる品が選ばれる場合などを考える。消費の理由を振り返る際、実際の使い勝手と地位の表示としての価値を分けてみられる。高価な品を買う行動がすべてこの効果ではなく、品質や希少性への評価とも区別する。値上げすれば必ず売れるという法則ではない。他者が持たないことを好むスノッブ効果とも異なる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":61,"display_id":61,"aliases":["Veblen effect","ベブレン効果"],"related_theory_ids":["kb_107","kb_474","kb_514","kb_1021"],"canonical_id":"kb_1022","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Harvey Leibenstein；Thorstein Veblenの顕示的消費に由来","works":["Bandwagon, Snob, and Veblen Effects in the Theory of Consumers’ Demand (1950)"],"sources":[{"title":"Bandwagon, Snob, and Veblen Effects in the Theory of Consumers’ Demand (1950)","url":"https://academic.oup.com/qje/article-abstract/64/2/183/1931945"}],"status":"書誌確認済み","note":"顕示的消費はより広い概念なので正式同義語へ入れない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1023","title":"ディスポジション効果","summary":"利益が出た資産は早く売り、損失が出た資産は長く持ち続ける傾向。利益を確定する安心と、損失を認める抵抗が、現在の見込みとは別に判断へ入り込む場合がある。過去の取得価格への感情と、今後の判断根拠を分けて振り返る概念として使える。ただし税、手数料、資金需要、合理的な見通しによる売買もあり、個別の保有を直ちに誤りとは決められない。損失回避を資産の処分行動に適用した現象で、売買の推奨ルールではない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":62,"display_id":62,"aliases":["disposition effect"],"related_theory_ids":["kb_134","kb_757","kb_273"],"canonical_id":"kb_1023","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Hersh Shefrin / Meir Statman","works":["The Disposition to Sell Winners Too Early and Ride Losers Too Long (1985)"],"sources":[{"title":"The Disposition to Sell Winners Too Early and Ride Losers Too Long (1985)","url":"https://doi.org/10.1111/j.1540-6261.1985.tb05002.x"}],"status":"書誌確認済み","note":"現象の理解に限定し、特定資産の売買判断を勧めない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1024","title":"近視眼的損失回避","summary":"損失を強く嫌う傾向と、結果を短い間隔で評価することが組み合わさり、長期とは異なるリスク判断になるという説明。変動する成果を毎日確かめると、小さな下落を何度も経験して慎重になりやすい場合などを考える。評価頻度が自分の反応にどう影響するかを振り返る手掛かりになる。長く見ればどんなリスクも安全になるという意味ではなく、必要な監視を減らす指示でもない。現在の利益を優先する現在バイアスとは機序が異なる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":63,"display_id":63,"aliases":["myopic loss aversion"],"related_theory_ids":["kb_134","kb_175"],"canonical_id":"kb_1024","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Shlomo Benartzi / Richard H. Thaler","works":["Myopic Loss Aversion and the Equity Premium Puzzle (1995)"],"sources":[{"title":"Myopic Loss Aversion and the Equity Premium Puzzle (1995)","url":"https://doi.org/10.2307/2118511"}],"status":"書誌確認済み","note":"評価間隔と損失回避の組合せ。長期投資の効能保証ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1025","title":"確率マッチング","summary":"起こる結果の頻度に合わせて、予測や選択の割合を配分する傾向。独立に赤が7割出る課題で、赤を7割、青を3割予測するような例である。正答数だけを最大化するなら毎回赤を選ぶ方が有利な設定でも、割合を合わせる行動が見られる。確率的な選択を点検する際、目的が予測の的中、探索、分配のどれかを明確にする。環境が変わる場合や探索に価値がある場合を含め、すべての確率的選択を非合理とはしない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":64,"display_id":64,"aliases":["probability matching"],"related_theory_ids":["kb_755","kb_713","kb_287"],"canonical_id":"kb_1025","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Nir Vulkan","works":["An Economist’s Perspective on Probability Matching (2000)"],"sources":[{"title":"An Economist’s Perspective on Probability Matching (2000)","url":"https://doi.org/10.1111/1467-6419.00106"}],"status":"書誌確認済み","note":"強化率と行動配分のマッチング法則とは別概念。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1038","title":"投影バイアス","summary":"現在の好みや身体状態が将来も続くと見積もり、将来の自分の選好の変化を十分に考慮できない傾向。空腹時に翌週の食料を買うと、後で必要な量より多く選ぶ場合などがある。先の予定や購入を決めるときは、今とは異なる状態でどう感じるかを具体的に想像し、過去の記録も確かめる。単に現在の利益を優先する現在バイアスとは違い、将来の好みの予測が対象になる。将来は今と必ず違うと決めつけるのではなく、変化の可能性を見積もる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":65,"display_id":65,"aliases":["projection bias"],"related_theory_ids":["kb_429","kb_234","kb_175"],"canonical_id":"kb_1038","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"George Loewenstein / Ted O’Donoghue / Matthew Rabin","works":["Projection Bias in Predicting Future Utility (2003)"],"sources":[{"title":"Projection Bias in Predicting Future Utility (2003)","url":"https://doi.org/10.1162/003355303322552784"}],"status":"書誌確認済み","note":"ホット・コールド共感ギャップと接点があるが、将来選好への投影に焦点を置く。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1039","title":"認識ヒューリスティック","summary":"二つの対象の一方だけを知っている場合、その知っている方がある基準で大きいと推測する簡便な方略。二都市の人口を比べる際、名前を聞いたことのある都市を選ぶような例である。知っているかどうかが対象の基準と相関する環境では有効な場合がある。聞き覚えを根拠にした判断では、その相関が今の環境にあるかを確かめる。広告で知られた品など、知名度が品質と結び付かない場面では外れうる。再認主導意思決定モデルとは異なる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":66,"display_id":66,"aliases":["recognition heuristic","再認ヒューリスティック"],"related_theory_ids":["kb_597","kb_825","kb_754"],"canonical_id":"kb_1039","legacy_ids":[],"knowledge_type":"heuristic","provenance":{"attribution":"Daniel G. Goldstein / Gerd Gigerenzer","works":["Models of Ecological Rationality: The Recognition Heuristic (2002)"],"sources":[{"title":"Models of Ecological Rationality: The Recognition Heuristic (2002)","url":"https://doi.org/10.1037/0033-295X.109.1.75"}],"status":"書誌確認済み","note":"recognition-primed decisionと同義にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1040","title":"Take-the-bestヒューリスティック","summary":"予測力の高い手掛かりから順に二候補を比べ、最初に差がついた手掛かりだけで判断を止める方略。どちらの都市が大きいかを考えるとき、重要と見積もる特徴から調べ、区別できた段階で選ぶ。すべての情報を合計せずとも、不確実な環境では良い予測になる場合がある。手掛かりの順序や環境構造に依存するため、重要な条件を無視してよいという勧めではない。必須条件の確認や、安全に関わる判断には別の点検が必要になる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":67,"display_id":67,"aliases":["take-the-best heuristic"],"related_theory_ids":["kb_754","kb_277","kb_597"],"canonical_id":"kb_1040","legacy_ids":[],"knowledge_type":"heuristic","provenance":{"attribution":"Gerd Gigerenzer / Daniel G. Goldstein","works":["Reasoning the fast and frugal way (1996)"],"sources":[{"title":"Reasoning the fast and frugal way (1996)","url":"https://doi.org/10.1037/0033-295X.103.4.650"}],"status":"書誌確認済み","note":"二候補間での識別と停止のルール。一般的な最善選択の意味ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1041","title":"側面ごとの消去法","summary":"選択肢のある側面に着目し、その側面を満たさない候補を除く過程を繰り返す選択モデル。住まいを選ぶ際、通勤時間、費用、設備などで候補を順次絞る場合が身近な例になる。原モデルでは側面が重みに応じて確率的に選ばれる点を含む。実務では除外条件を明示する手掛かりになるが、条件の順序で残る候補が変わる可能性を確かめる。全属性の得点を足す方法や、最初の差で二候補を選ぶTake-the-bestとは異なる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":68,"display_id":68,"aliases":["elimination by aspects"],"related_theory_ids":["kb_277","kb_275","kb_754"],"canonical_id":"kb_1041","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Amos Tversky","works":["Elimination by aspects: A theory of choice (1972)"],"sources":[{"title":"Elimination by aspects: A theory of choice (1972)","url":"https://doi.org/10.1037/h0032955"}],"status":"書誌確認済み","note":"日本語の手順例と、原著の確率的モデルを区別する。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1042","title":"スラッジ","summary":"必要な行動を妨げる過大な手間、分かりにくさ、待ち時間などの摩擦を点検する概念。申請に何度も同じ情報を入力させる、解約方法が見つからないといった状況で、形式上の選択肢があっても利用しにくくなる。改善では工程や負担を可視化し、目的に比べ不要な障壁を減らす。本人を助ける確認手順まで無条件に取り除く意味ではない。ナッジの単なる反対語ではなく、利益、必要性、分配の不公平も検討して摩擦を評価する。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":69,"display_id":69,"aliases":["sludge"],"related_theory_ids":["kb_181","kb_178","kb_179"],"canonical_id":"kb_1042","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Cass R. Sunstein","works":["Sludge Audits (2020)"],"sources":[{"title":"Sludge Audits (2020)","url":"https://doi.org/10.1017/bpp.2019.32"}],"status":"書誌確認済み","note":"行動摩擦一般のうち過大・不必要な負担を評価する規範的観点。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1043","title":"不平等回避","summary":"自分と他者の取り分の不平等が、不利益でも有利でも効用に影響すると捉える社会的選好のモデル。自分の取り分が増えても極端に不公平な分配を拒んだり、自分の利益を減らして差を縮めたりする行動を考える。交渉や分配では総額だけでなく、誰とどう比べられているかを確かめる視点になる。人は全員同じ平等を求めるわけではなく、貢献、手続き、関係によっても反応は変わる。すべての協力や公正判断を説明する唯一の理論ではない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":70,"display_id":70,"aliases":["inequity aversion"],"related_theory_ids":["kb_031","kb_768","kb_798"],"canonical_id":"kb_1043","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Ernst Fehr / Klaus M. Schmidt","works":["A Theory of Fairness, Competition, and Cooperation (1999)"],"sources":[{"title":"A Theory of Fairness, Competition, and Cooperation (1999)","url":"https://doi.org/10.1162/003355399556151"}],"status":"書誌確認済み","note":"inequity aversionのモデルを中心に説明。分配的公正全体の同義ではない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1044","title":"生態学的合理性","summary":"判断方略の良し悪しを、形式的に複雑かどうかだけでなく、用いる環境の情報構造との適合で評価する立場。少数の確かな手掛かりで判断する方法が、データが少ない場面では複雑な計算よりよい予測になる場合がある。方略を選ぶ際、利用できる情報、ノイズ、時間、目的を確かめる。単純な直感はいつでも優れるという主張ではなく、どの条件でどの方略が役立つかを検証する。環境保護の行動を合理的と呼ぶ意味とは異なる。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-d","taxonomy_order":71,"display_id":71,"aliases":["ecological rationality"],"related_theory_ids":["kb_754","kb_287","kb_277"],"canonical_id":"kb_1044","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Gerd Gigerenzerほか","works":["Ecological rationality: Rethinking behavioural economics（著者公開資料）"],"sources":[{"title":"Ecological rationality: Rethinking behavioural economics（著者公開資料）","url":"https://pure.mpg.de/pubman/item/item_3492412_12"}],"status":"書誌確認済み","note":"認識・Take-the-bestは個別方略。本カードは環境適合の評価枠組み。"},"quotation":null,"access_tier":"complete"},{"id":"kb_520","taxonomy_order":1,"display_id":72,"aliases":["self-determination theory"],"related_theory_ids":["kb_736","kb_899","kb_941","kb_884","kb_833","kb_1049"]},{"id":"kb_884","taxonomy_order":2,"display_id":73,"aliases":["overjustification effect","オーバージャスティフィケーション効果"],"related_theory_ids":["kb_168","kb_947","kb_520"]},{"id":"kb_899","taxonomy_order":3,"display_id":74,"aliases":["Maslow hierarchy of needs","欲求階層理論","欲求五段階説"],"related_theory_ids":["kb_520","kb_730"]},{"id":"kb_750","taxonomy_order":4,"display_id":75,"aliases":["expectancy-value theory","期待×価値理論"],"related_theory_ids":["kb_169","kb_804","kb_833","kb_168","kb_992"]},{"id":"kb_168","taxonomy_order":5,"display_id":76,"aliases":[],"related_theory_ids":["kb_774","kb_776","kb_884","kb_750"]},{"id":"kb_751","taxonomy_order":6,"display_id":77,"aliases":["temporal motivation theory","TMT"],"related_theory_ids":["kb_175","kb_183"]},{"id":"kb_183","taxonomy_order":7,"display_id":78,"aliases":[],"related_theory_ids":["kb_751"]},{"id":"kb_260","taxonomy_order":8,"display_id":79,"aliases":[],"related_theory_ids":[]},{"id":"kb_261","taxonomy_order":9,"display_id":80,"aliases":[],"related_theory_ids":[]},{"id":"kb_833","taxonomy_order":10,"display_id":81,"aliases":["self-concordance model","自己一致目標モデル"],"related_theory_ids":["kb_750","kb_520"]},{"id":"kb_737","taxonomy_order":11,"display_id":82,"aliases":["Yerkes-Dodson law","逆U字仮説","覚醒水準とパフォーマンス"],"related_theory_ids":["kb_736","kb_493"]},{"id":"kb_184","taxonomy_order":12,"display_id":83,"aliases":[],"related_theory_ids":["kb_1028"]},{"id":"kb_185","taxonomy_order":13,"display_id":84,"aliases":[],"related_theory_ids":[]},{"id":"kb_189","taxonomy_order":14,"display_id":85,"aliases":[],"related_theory_ids":[]},{"id":"kb_186","taxonomy_order":15,"display_id":86,"aliases":[],"related_theory_ids":[]},{"id":"kb_167","taxonomy_order":16,"display_id":87,"aliases":["goal-setting theory"],"related_theory_ids":["kb_749","kb_1026","kb_1037","kb_1072"]},{"id":"kb_170","taxonomy_order":17,"display_id":88,"aliases":[],"related_theory_ids":["kb_832"]},{"id":"kb_187","taxonomy_order":18,"display_id":89,"aliases":[],"related_theory_ids":["kb_992"]},{"id":"kb_188","taxonomy_order":19,"display_id":90,"aliases":[],"related_theory_ids":[]},{"id":"kb_172","taxonomy_order":20,"display_id":91,"aliases":["implementation intentions"],"related_theory_ids":["kb_832","kb_943","kb_944","kb_749","kb_974","kb_1026","kb_1027","kb_1036","kb_1072","kb_1075"]},{"id":"kb_171","taxonomy_order":21,"display_id":92,"aliases":[],"related_theory_ids":["kb_537"]},{"id":"kb_537","taxonomy_order":22,"display_id":93,"aliases":[],"related_theory_ids":["kb_171","kb_1037","kb_1063"]},{"id":"kb_174","taxonomy_order":23,"display_id":94,"aliases":["precommitment"],"related_theory_ids":["kb_173","kb_1011"]},{"id":"kb_749","taxonomy_order":24,"display_id":95,"aliases":["mental contrasting","WOOP","MCII","Mental Contrasting with Implementation Intentions","願望実現の4ステップ"],"related_theory_ids":["kb_167","kb_172"]},{"id":"kb_832","taxonomy_order":25,"display_id":96,"aliases":["goal shielding","目標遮蔽"],"related_theory_ids":["kb_170","kb_172"]},{"id":"kb_572","taxonomy_order":26,"display_id":97,"aliases":[],"related_theory_ids":["kb_911"]},{"id":"kb_173","taxonomy_order":27,"display_id":98,"aliases":["commitment device"],"related_theory_ids":["kb_174"]},{"id":"kb_539","taxonomy_order":28,"display_id":99,"aliases":[],"related_theory_ids":["kb_722"]},{"id":"kb_834","taxonomy_order":29,"display_id":100,"aliases":["episodic future thinking","EFT"],"related_theory_ids":["kb_753","kb_752"]},{"id":"kb_1026","title":"意図と行動のギャップ","summary":"行うつもりがあることと、実際に実行することの間に隔たりがあること。運動しようと決めても、時間や場所を決めず、仕事後には始められない場合などがある。意欲を高めるだけでなく、機会、手順、障害、思い出すきっかけまで確かめる必要を示す。実行意図や環境の調整を検討する入口になるが、ギャップ自体は一つの原因を指さない。実行できなかった人を無責任と評価する名称ではなく、資源や機会の制約も含めて考える。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-m","taxonomy_order":30,"display_id":101,"aliases":["intention-behavior gap","intention–behaviour gap"],"related_theory_ids":["kb_172","kb_181","kb_167"],"canonical_id":"kb_1026","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Paschal Sheeran","works":["Intention–Behavior Relations: A Conceptual and Empirical Review (2002)"],"sources":[{"title":"Intention–Behavior Relations: A Conceptual and Empirical Review (2002)","url":"https://doi.org/10.1080/14792772143000003"}],"status":"書誌確認済み","note":"理論名ではなく観察される隔たりの概念。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1027","title":"計画的行動理論","summary":"行動への態度、周囲が期待していると感じる規範、自分に実行できるという認識が意図を形成し、意図と実際の統制可能性が行動に関わるとする理論。研修への参加を考えるなら、有益と思うか、周囲の期待、時間や手段の確保を分けて尋ねられる。計画は立てたのに実行しない理由を整理する枠組みになる。ただし意図だけで行動は決まらず、習慣、感情、制度的制約もある。全行動を精密に予測する式として使わない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-m","taxonomy_order":31,"display_id":102,"aliases":["theory of planned behavior","theory of planned behaviour"],"related_theory_ids":["kb_169","kb_172","kb_455"],"canonical_id":"kb_1027","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Icek Ajzen","works":["The theory of planned behavior (1991)"],"sources":[{"title":"The theory of planned behavior (1991)","url":"https://doi.org/10.1016/0749-5978(91)90020-T"}],"status":"書誌確認済み","note":"TPBは補助語。実際の統制と知覚された統制を区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_180","taxonomy_order":1,"display_id":103,"aliases":[],"related_theory_ids":["kb_944","kb_1028","kb_1029"]},{"id":"kb_535","taxonomy_order":2,"display_id":104,"aliases":[],"related_theory_ids":["kb_1028"]},{"id":"kb_541","taxonomy_order":3,"display_id":105,"aliases":[],"related_theory_ids":[]},{"id":"kb_533","taxonomy_order":4,"display_id":106,"aliases":[],"related_theory_ids":[]},{"id":"kb_534","taxonomy_order":5,"display_id":107,"aliases":[],"related_theory_ids":[]},{"id":"kb_178","taxonomy_order":6,"display_id":108,"aliases":[],"related_theory_ids":["kb_179","kb_966","kb_1033","kb_1042","kb_1067","kb_1070"]},{"id":"kb_179","taxonomy_order":7,"display_id":109,"aliases":[],"related_theory_ids":["kb_178","kb_1030","kb_1033","kb_1042"]},{"id":"kb_528","taxonomy_order":8,"display_id":110,"aliases":[],"related_theory_ids":["kb_943","kb_966"]},{"id":"kb_181","taxonomy_order":9,"display_id":111,"aliases":[],"related_theory_ids":["kb_943","kb_1026","kb_1032","kb_1033","kb_1034","kb_1042"]},{"id":"kb_177","taxonomy_order":10,"display_id":112,"aliases":[],"related_theory_ids":["kb_842"]},{"id":"kb_182","taxonomy_order":11,"display_id":113,"aliases":["temptation bundling"],"related_theory_ids":[]},{"id":"kb_438","taxonomy_order":12,"display_id":114,"aliases":[],"related_theory_ids":[]},{"id":"kb_943","taxonomy_order":13,"display_id":115,"aliases":["Fogg Behavior Model","FBM","B=MAP"],"related_theory_ids":["kb_181","kb_528","kb_172","kb_944","kb_529","kb_1032"]},{"id":"kb_944","taxonomy_order":14,"display_id":116,"aliases":["transtheoretical model","TTM","トランスセオレティカル・モデル","変化のステージモデル"],"related_theory_ids":["kb_180","kb_943","kb_172","kb_1032","kb_1036"]},{"id":"kb_1028","title":"習慣不連続性仮説","summary":"引っ越しや転職などで行動の手掛かりとなる状況が変わると、古い習慣の自動的な実行が弱まり、行動を見直す機会が生まれるという仮説。通勤経路が変わったときに移動手段を選び直す場合などが例になる。生活の移行期には、望む行動を実行しやすい手順や物の配置を早めに作るとよい。変化だけで良い習慣が自然に身につくわけではなく、新しい機会や支援が必要である。継続が途切れた人の意欲不足を意味しない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":15,"display_id":117,"aliases":["habit discontinuity hypothesis"],"related_theory_ids":["kb_535","kb_180","kb_184"],"canonical_id":"kb_1028","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Bas Verplanken / Deborah Roy","works":["Empowering interventions to promote sustainable lifestyles (2016)"],"sources":[{"title":"Empowering interventions to promote sustainable lifestyles (2016)","url":"https://www.sciencedirect.com/science/article/pii/S0272494415300487"}],"status":"書誌確認済み","note":"状況変化を活かした介入の検討。新鮮なスタートの心理的区切りとは異なる。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1029","title":"行動の波及効果","summary":"一つの行動やそれを促す介入が、直接は対象としていなかった別の行動にも影響すること。節電を始めて他の省資源行動も増える場合もあれば、良いことをした安心から別の消費が増える場合もある。施策の評価では狙った行動だけでなく、隣接する行動への正負の影響も確認する。二つの行動が一緒に起きたという相関だけでは波及とは言えない。モラル・ライセンシングは負の波及を説明しうる一つの機序で、全体の同義語ではない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":16,"display_id":118,"aliases":["behavioral spillover","behavioural spillover"],"related_theory_ids":["kb_883","kb_443","kb_180"],"canonical_id":"kb_1029","legacy_ids":[],"knowledge_type":"phenomenon","provenance":{"attribution":"Paul Dolan / Matteo M. Galizzi","works":["Like ripples on a pond: Behavioral spillovers and their implications (2015)"],"sources":[{"title":"Like ripples on a pond: Behavioral spillovers and their implications (2015)","url":"https://researchonline.lse.ac.uk/id/eprint/60804/1/__lse.ac.uk_storage_LIBRARY_Secondary_libfile_shared_repository_Content_Dolan%2C%20P_Like%20ripples_Dolan_Like%20ripples_2015.pdf"}],"status":"書誌確認済み","note":"正負の双方を扱う。単なる行動の共起と因果的な波及を区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1030","title":"社会規範フィードバック","summary":"自分の行動を、関連する集団の実際の行動や望ましい基準と比較して伝える方法。電力使用量を近い条件の世帯と比べて示すことなどが例になる。介入では比較対象を適切に選び、実際の分布を正確に伝える。平均より良い行動をしていた人が平均へ戻る逆効果もあるため、望ましい行動への承認を組み合わせるなど設計が必要になる。単に「皆がやっている」と圧力をかける方法ではなく、効果の方向を測定して確かめる技法である。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":17,"display_id":119,"aliases":["social norms feedback","normative feedback"],"related_theory_ids":["kb_455","kb_266","kb_179"],"canonical_id":"kb_1030","legacy_ids":[],"knowledge_type":"method","provenance":{"attribution":"P. Wesley Schultzほか","works":["The constructive, destructive, and reconstructive power of social norms (2007)"],"sources":[{"title":"The constructive, destructive, and reconstructive power of social norms (2007)","url":"https://pubmed.ncbi.nlm.nih.gov/17576283/"}],"status":"書誌確認済み","note":"記述的規範と命令的規範の相互作用、ブーメラン効果を含める。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1032","title":"COM-Bモデル","summary":"行動の成立を、能力、機会、動機の相互作用として捉えるモデル。実行しない人に意欲を求める前に、方法を知っているか、必要な場所や道具があるか、習慣や感情がどう関わるかを分けて調べる。例えば研修後に手順を使わない場合、知識不足と時間不足では支援が異なる。介入を選ぶ前の問題整理に使えるが、三項目を埋めるだけで効果が保証されるわけではない。本人の希望、環境の制約、実際の結果を確かめながら設計する。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":18,"display_id":120,"aliases":["COM-B model","COM-B"],"related_theory_ids":["kb_943","kb_944","kb_181","kb_169","kb_1033"],"canonical_id":"kb_1032","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Susan Michie / Maartje M. van Stralen / Robert West","works":["The behaviour change wheel (2011)"],"sources":[{"title":"The behaviour change wheel (2011)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3096582/"}],"status":"書誌確認済み","note":"COM-Bは行動変容の輪の中心モデル。BCW全体を正式別名にしない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1033","title":"EASTフレームワーク","summary":"行動を促す設計を、簡単に、魅力的に、社会的に、適切な時に、という四つの観点で点検する実践枠組み。提出を増やしたいなら入力工程を減らし、要点を目立たせ、適切な規範情報を伝え、準備できる時点で案内する。施策の案出に使い、その後は比較や実験で結果を確かめる。人を必ず動かす四法則ではなく、対象や状況で有効性は変わる。誤った社会情報や、本人の選択を妨げる誘導を正当化しない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":19,"display_id":121,"aliases":["EAST framework","EAST"],"related_theory_ids":["kb_179","kb_178","kb_181","kb_1032"],"canonical_id":"kb_1033","legacy_ids":[],"knowledge_type":"method","provenance":{"attribution":"Behavioural Insights Team","works":["EAST: Four simple ways to apply behavioural insights (2014；改訂版あり)"],"sources":[{"title":"EAST: Four simple ways to apply behavioural insights (2014；改訂版あり)","url":"https://www.bi.team/publications/east-four-simple-ways-to-apply-behavioural-insights/"}],"status":"書誌確認済み","note":"学術的な単一理論ではなく設計の実践枠組み。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1034","title":"健康信念モデル","summary":"健康に関わる行動を、問題が自分に起こる可能性や重大さ、行動の利益と障壁、きっかけなどの認識から理解するモデル。健診を勧める場合、必要性を理解していないのか、費用や時間が障害なのかを分けて聞く。恐ろしさだけを強調せず、実行できる選択肢を確かめる手掛かりになる。後の拡張では自己効力感なども考慮する。信念だけで行動が決まるとは限らず、医療へのアクセスや制度の制約もある。個別の診断や治療判断に代わるものではない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":20,"display_id":122,"aliases":["health belief model"],"related_theory_ids":["kb_169","kb_228","kb_181"],"canonical_id":"kb_1034","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Irwin M. Rosenstock","works":["Historical Origins of the Health Belief Model (1974)"],"sources":[{"title":"Historical Origins of the Health Belief Model (1974)","url":"https://doi.org/10.1177/109019817400200403"}],"status":"書誌確認済み","note":"健康行動の説明モデル。一般場面への例は応用であり医療的効能を示さない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1035","title":"保護動機理論","summary":"脅威への評価と、対処できるかの評価が、防御的な行動の意図にどう関わるかを説明する理論。情報セキュリティの注意喚起では、被害の深刻さだけでなく、推奨行動の有効性や自分に実行できる感覚が重要になる。警告と具体的な対処手順を一緒に設計するために使える。後の拡張ではコストや報酬なども扱う。恐怖を強めるほど良いという理論ではなく、回避や否認が起きる可能性もある。意図と実行、知覚と実際の能力を分けて評価する。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":21,"display_id":123,"aliases":["protection motivation theory"],"related_theory_ids":["kb_169","kb_228","kb_207"],"canonical_id":"kb_1035","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Ronald W. Rogers","works":["A Protection Motivation Theory of Fear Appeals and Attitude Change (1975)"],"sources":[{"title":"A Protection Motivation Theory of Fear Appeals and Attitude Change (1975)","url":"https://doi.org/10.1080/00223980.1975.9915803"}],"status":"書誌確認済み","note":"1975年の原提案と後の拡張の違いを明記。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1036","title":"健康行動プロセスアプローチ","summary":"健康行動を始めようとする動機形成と、その後の計画、実行、維持、再開を分けて考える枠組み。運動したいと思う段階と、忙しい週にどう続けるかを決める段階では、必要な支援が違う。いつどこで行うかに加え、障害が出た際の対処や中断後の再開も具体化する。各段階で自己効力感の役割を考えるが、誰もが固定した順序を一度だけ進むわけではない。生活上の資源や本人の希望を確認し、モデルを治療手順や成果の保証として使わない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-h","taxonomy_order":22,"display_id":124,"aliases":["health action process approach","HAPA"],"related_theory_ids":["kb_944","kb_172","kb_169"],"canonical_id":"kb_1036","legacy_ids":[],"knowledge_type":"model","provenance":{"attribution":"Ralf Schwarzer","works":["Modeling Health Behavior Change (2008)"],"sources":[{"title":"Modeling Health Behavior Change (2008)","url":"https://doi.org/10.1111/j.1464-0597.2007.00325.x"}],"status":"書誌確認済み","note":"段階という語だけで行動変容ステージモデルへ統合しない。"},"quotation":null,"access_tier":"complete"},{"id":"kb_536","taxonomy_order":1,"display_id":125,"aliases":["operant conditioning"],"related_theory_ids":["kb_900","kb_209","kb_048","kb_440","kb_1031"]},{"id":"kb_900","taxonomy_order":2,"display_id":126,"aliases":["classical conditioning","レスポンデント条件づけ","パブロフ型条件づけ"],"related_theory_ids":["kb_536","kb_208","kb_440"]},{"id":"kb_437","taxonomy_order":3,"display_id":127,"aliases":[],"related_theory_ids":["kb_947","kb_1031"]},{"id":"kb_440","taxonomy_order":4,"display_id":128,"aliases":[],"related_theory_ids":["kb_831","kb_900","kb_945","kb_536","kb_049"]},{"id":"kb_048","taxonomy_order":5,"display_id":129,"aliases":["intermittent reinforcement"],"related_theory_ids":["kb_536"]},{"id":"kb_209","taxonomy_order":6,"display_id":130,"aliases":["negative reinforcement","負の強化"],"related_theory_ids":["kb_536"]},{"id":"kb_735","taxonomy_order":7,"display_id":131,"aliases":["observational learning","social learning theory","社会的認知理論","モデリング"],"related_theory_ids":["kb_169","kb_123"]},{"id":"kb_200","taxonomy_order":8,"display_id":132,"aliases":["spacing effect","分散学習効果"],"related_theory_ids":["kb_738","kb_921","kb_1077"]},{"id":"kb_199","taxonomy_order":9,"display_id":133,"aliases":["testing effect","テスト効果","retrieval practice effect"],"related_theory_ids":["kb_738","kb_741","kb_747","kb_831","kb_829","kb_879","kb_1076","kb_1077","kb_1078"]},{"id":"kb_201","taxonomy_order":10,"display_id":134,"aliases":["desirable difficulties"],"related_theory_ids":["kb_747"]},{"id":"kb_747","taxonomy_order":11,"display_id":135,"aliases":["interleaving effect","交互学習","混合練習"],"related_theory_ids":["kb_199","kb_201"]},{"id":"kb_748","taxonomy_order":12,"display_id":136,"aliases":["self-explanation effect","自己説明学習"],"related_theory_ids":["kb_723","kb_741","kb_744","kb_828","kb_1050","kb_1076","kb_1077","kb_1079"]},{"id":"kb_198","taxonomy_order":13,"display_id":137,"aliases":["deliberate practice"],"related_theory_ids":["kb_917","kb_947"]},{"id":"kb_049","taxonomy_order":14,"display_id":138,"aliases":[],"related_theory_ids":["kb_440"]},{"id":"kb_415","taxonomy_order":15,"display_id":139,"aliases":["elaborative rehearsal"],"related_theory_ids":["kb_744"]},{"id":"kb_828","taxonomy_order":16,"display_id":140,"aliases":["protégé effect","プロテジェ・エフェクト"],"related_theory_ids":["kb_748","kb_741","kb_904","kb_948","kb_1050"]},{"id":"kb_945","taxonomy_order":17,"display_id":141,"aliases":["habituation","慣れの学習"],"related_theory_ids":["kb_440","kb_211","kb_268","kb_946","kb_960"]},{"id":"kb_946","taxonomy_order":18,"display_id":142,"aliases":["sensitization","感作"],"related_theory_ids":["kb_211","kb_922","kb_945"]},{"id":"kb_947","taxonomy_order":19,"display_id":143,"aliases":["learned industriousness","学習性勤勉性"],"related_theory_ids":["kb_437","kb_198","kb_884"]},{"id":"kb_948","taxonomy_order":20,"display_id":144,"aliases":["scaffolding","スキャフォールディング"],"related_theory_ids":["kb_169","kb_828","kb_952","kb_904"]},{"id":"kb_1031","title":"行動形成（シェイピング）","summary":"目標行動に少しずつ近づく反応を選んで強化し、まだできない行動を形成する学習手続き。発表練習なら、まず短く声に出すこと、次に要点を伝えることへと、達成基準を段階的に上げる。現在の行動、次の小さな基準、強化するタイミングを具体化して使う。作業を分割するだけではシェイピングとは限らず、結果に応じた強化の条件が重要である。急に基準を上げたり、相手が望まない目標へ誘導したりしない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-l","taxonomy_order":21,"display_id":145,"aliases":["shaping","逐次接近法"],"related_theory_ids":["kb_536","kb_437","kb_529"],"canonical_id":"kb_1031","legacy_ids":[],"knowledge_type":"method","provenance":{"attribution":"B. F. Skinner；OpenStax（参照教材）","works":["Psychology 2e, 6.3 Operant Conditioning"],"sources":[{"title":"Psychology 2e, 6.3 Operant Conditioning","url":"https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"}],"status":"書誌確認済み","note":"習慣設計にも使えるが、機序に合わせ学習・強化へ配置。"},"quotation":null,"access_tier":"complete"},{"id":"kb_1037","title":"フィードバック介入理論","summary":"成績についての情報が、課題の処理、学び方、自己への注意のどこへ向けられるかによって、その後の成績が変わると考える理論。人格への評価ばかりを伝えると、作業の改善より自分を守ることへ注意が移る場合がある。指導では具体的な課題、目標との差、次に試す行動へ焦点を合わせ、結果を確かめる。フィードバックは必ず成績を高めるわけではない。理論は効果の違いを説明する枠組みで、唯一の正しい伝え方を決めるものではない。","category_id":"behavioral-science","category_title":"行動科学","subcategory_id":"behavioral-science-l","taxonomy_order":22,"display_id":146,"aliases":["feedback intervention theory"],"related_theory_ids":["kb_394","kb_537","kb_167"],"canonical_id":"kb_1037","legacy_ids":[],"knowledge_type":"theory","provenance":{"attribution":"Avraham N. Kluger / Angelo DeNisi","works":["The effects of feedback interventions on performance (1996)"],"sources":[{"title":"The effects of feedback interventions on performance (1996)","url":"https://doi.org/10.1037/0033-2909.119.2.254"}],"status":"書誌確認済み","note":"メタ分析と理論提案。SBI等の手順そのものとは区別。"},"quotation":null,"access_tier":"complete"},{"id":"kb_766","taxonomy_order":1,"display_id":1,"aliases":["job satisfaction","仕事満足度"],"related_theory_ids":["kb_764","kb_765","kb_890"]},{"id":"kb_890","taxonomy_order":2,"display_id":2,"aliases":["Herzberg two-factor theory","動機づけ・衛生理論"],"related_theory_ids":["kb_766","kb_764"]},{"id":"kb_767","taxonomy_order":3,"d