insert into release_technique_links select x."techniqueId",x."theoryId" from jsonb_to_recordset('[{"techniqueId":"master336-310","theoryId":"kb_1060","anchor":"kb_709","reason":"既存の後知恵バイアスの説明に、意思決定ジャーナルによる具体的な実践・理解を補う。"},{"techniqueId":"master336-056","theoryId":"kb_1048","anchor":"kb_394","reason":"既存の具体的フィードバックの説明に、SBIフィードバックによる具体的な実践・理解を補う。"},{"techniqueId":"master336-188","theoryId":"kb_1056","anchor":"kb_547","reason":"既存のタイムボックスの説明に、アイゼンハワー・マトリクスによる具体的な実践・理解を補う。"},{"techniqueId":"master336-189","theoryId":"kb_1075","anchor":"kb_547","reason":"既存のタイムボックスの説明に、タイムブロッキングによる具体的な実践・理解を補う。"},{"techniqueId":"master336-208","theoryId":"kb_1080","anchor":"kb_573","reason":"既存の二分法的思考の説明に、思考記録表による具体的な実践・理解を補う。"}]'::jsonb) x("techniqueId" text,"theoryId" text);
do $guard$ begin
 if exists(select 1 from public.theories t join release_new_ids n using(id)) then raise exception 'Reserved ID collision';end if;
 if exists(select 1 from release_technique_links l left join public.techniques t on t.id=l.technique_id where t.id is null or t.updated_at<>'2026-10-16T15:04:53.835328Z'::timestamptz) then raise exception 'Technique source changed';end if;
end $guard$;
insert into private.theory_reform_backups(phase,source_table,source_id,snapshot)
 select 'theory-release-20261018','theories',id,to_jsonb(t) from public.theories t
 union all select 'theory-release-20261018','theory_relations',source_id||'|'||target_id,to_jsonb(r) from public.theory_relations r
 union all select 'theory-release-20261018','techniques',id,to_jsonb(t) from public.techniques t where id in(select technique_id from release_technique_links);
-- Vacate category display numbers atomically; stable IDs never change.
update public.theories set display_id=-display_id where status='published';
insert into public.theories(id,title,summary,category_id,category_title,subcategory_id,taxonomy_order,display_id,display_order,aliases,related_theory_ids,canonical_id,legacy_ids,knowledge_type,provenance,access_tier,status)
 select c.id,c.title,c.summary,c.category_id,c.category_title,c.subcategory_id,c.taxonomy_order,c.display_id,c.display_id,c.aliases,'[]'::jsonb,c.canonical_id,c.legacy_ids,c.knowledge_type,c.provenance,'complete','published' from release_cards c join release_new_ids n using(id);
update public.theories t set aliases=c.aliases,display_id=c.display_id,taxonomy_order=c.taxonomy_order,updated_at=now()
 from release_cards c where t.id=c.id and not exists(select 1 from release_new_ids n where n.id=t.id);
insert into public.theory_relations(source_id,target_id,relation_type,review_status,rationale,priority)
 select x."sourceId",x."targetId",x.type,x."reviewStatus",x.rationale,x.priority from jsonb_to_recordset('[{"sourceId":"kb_858","targetId":"kb_957","type":"related","reviewStatus":"confirmed","rationale":"サブリミナル効果と認知的プライミングは説明対象・手法を区別しながら読める。閾下知覚の存在と、強力な購買操作という俗説を分離。subliminal primingは下位の実験手続きなので正式同義語にしない。","priority":100},{"sourceId":"kb_004","targetId":"kb_957","type":"related","reviewStatus":"confirmed","rationale":"サブリミナル効果と単純接触効果は説明対象・手法を区別しながら読める。閾下知覚の存在と、強力な購買操作という俗説を分離。subliminal primingは下位の実験手続きなので正式同義語にしない。","priority":100},{"sourceId":"kb_844","targetId":"kb_958","type":"related","reviewStatus":"confirmed","rationale":"信号検出理論と確率無視は説明対象・手法を区別しながら読める。SDTは自己決定理論と衝突するため検索補助語へ。","priority":100},{"sourceId":"kb_214","targetId":"kb_958","type":"related","reviewStatus":"confirmed","rationale":"信号検出理論と確率過大評価は説明対象・手法を区別しながら読める。SDTは自己決定理論と衝突するため検索補助語へ。","priority":100},{"sourceId":"kb_139","targetId":"kb_959","type":"related","reviewStatus":"confirmed","rationale":"ウェーバーの法則と対比効果は説明対象・手法を区別しながら読める。弁別閾は測定概念であり法則そのものの別名にはしない。","priority":100},{"sourceId":"kb_401","targetId":"kb_959","type":"related","reviewStatus":"confirmed","rationale":"ウェーバーの法則と限界効用逓減は説明対象・手法を区別しながら読める。弁別閾は測定概念であり法則そのものの別名にはしない。","priority":100},{"sourceId":"kb_945","targetId":"kb_960","type":"related","reviewStatus":"confirmed","rationale":"感覚順応と馴化は説明対象・手法を区別しながら読める。馴化は行動上の非連合学習。感覚順応と同義にしない。","priority":100},{"sourceId":"kb_268","targetId":"kb_960","type":"related","reviewStatus":"confirmed","rationale":"感覚順応と快楽順応は説明対象・手法を区別しながら読める。馴化は行動上の非連合学習。感覚順応と同義にしない。","priority":100},{"sourceId":"kb_596","targetId":"kb_961","type":"related","reviewStatus":"confirmed","rationale":"知覚的構えと確証バイアスは説明対象・手法を区別しながら読める。選択的知覚という広い項目を参照しつつ、期待による構えに限定して説明。","priority":100},{"sourceId":"kb_858","targetId":"kb_961","type":"related","reviewStatus":"confirmed","rationale":"知覚的構えと認知的プライミングは説明対象・手法を区別しながら読める。選択的知覚という広い項目を参照しつつ、期待による構えに限定して説明。","priority":100},{"sourceId":"kb_450","targetId":"kb_962","type":"related","reviewStatus":"confirmed","rationale":"ゲシュタルトの群化原理とパターン認識は説明対象・手法を区別しながら読める。知覚の原理群。ゲシュタルト療法とは別概念。","priority":100},{"sourceId":"kb_746","targetId":"kb_962","type":"related","reviewStatus":"confirmed","rationale":"ゲシュタルトの群化原理とチャンク化は説明対象・手法を区別しながら読める。知覚の原理群。ゲシュタルト療法とは別概念。","priority":100},{"sourceId":"kb_858","targetId":"kb_963","type":"related","reviewStatus":"confirmed","rationale":"トップダウン処理・ボトムアップ処理と認知的プライミングは説明対象・手法を区別しながら読める。一つの比較枠組みとして収録。片方だけの語は関連検索語にする。","priority":100},{"sourceId":"kb_450","targetId":"kb_963","type":"related","reviewStatus":"confirmed","rationale":"トップダウン処理・ボトムアップ処理とパターン認識は説明対象・手法を区別しながら読める。一つの比較枠組みとして収録。片方だけの語は関連検索語にする。","priority":100},{"sourceId":"kb_570","targetId":"kb_964","type":"related","reviewStatus":"confirmed","rationale":"予測符号化理論とベイズ更新は説明対象・手法を区別しながら読める。視覚皮質の計算モデルを起点とする。自由エネルギー原理そのものとは同義にしない。","priority":100},{"sourceId":"kb_450","targetId":"kb_964","type":"related","reviewStatus":"confirmed","rationale":"予測符号化理論とパターン認識は説明対象・手法を区別しながら読める。視覚皮質の計算モデルを起点とする。自由エネルギー原理そのものとは同義にしない。","priority":100},{"sourceId":"kb_493","targetId":"kb_965","type":"related","reviewStatus":"confirmed","rationale":"注意資源理論と認知負荷理論は説明対象・手法を区別しながら読める。単一資源説と複数資源説を混同せず、容量という説明の水準を示す。","priority":100},{"sourceId":"kb_745","targetId":"kb_965","type":"related","reviewStatus":"confirmed","rationale":"注意資源理論とワーキングメモリ・モデルは説明対象・手法を区別しながら読める。単一資源説と複数資源説を混同せず、容量という説明の水準を示す。","priority":100},{"sourceId":"kb_528","targetId":"kb_966","type":"related","reviewStatus":"confirmed","rationale":"アフォーダンスと環境デザインは説明対象・手法を区別しながら読める。J. J. Gibsonの生態学的知覚論。知覚されたアフォーダンスやシグニファイアと区別。","priority":100},{"sourceId":"kb_178","targetId":"kb_966","type":"related","reviewStatus":"confirmed","rationale":"アフォーダンスと選択アーキテクチャは説明対象・手法を区別しながら読める。J. J. Gibsonの生態学的知覚論。知覚されたアフォーダンスやシグニファイアと区別。","priority":100},{"sourceId":"kb_531","targetId":"kb_967","type":"related","reviewStatus":"confirmed","rationale":"注意残余とツァイガルニク効果は説明対象・手法を区別しながら読める。注意残余と一般的なマルチタスクのコストを同一視しない。","priority":100},{"sourceId":"kb_493","targetId":"kb_967","type":"related","reviewStatus":"confirmed","rationale":"注意残余と認知負荷理論は説明対象・手法を区別しながら読める。注意残余と一般的なマルチタスクのコストを同一視しない。","priority":100},{"sourceId":"kb_017","targetId":"kb_968","type":"related","reviewStatus":"confirmed","rationale":"注意の捕捉とカクテルパーティー効果は説明対象・手法を区別しながら読める。外因的刺激と目標による制御の関係は研究上の論点。","priority":100},{"sourceId":"kb_872","targetId":"kb_968","type":"related","reviewStatus":"confirmed","rationale":"注意の捕捉と非注意性盲目は説明対象・手法を区別しながら読める。外因的刺激と目標による制御の関係は研究上の論点。","priority":100},{"sourceId":"kb_872","targetId":"kb_969","type":"related","reviewStatus":"confirmed","rationale":"絶対閾と非注意性盲目は説明対象・手法を区別しながら読める。心理物理学の測定概念。無意識の処理の有無を単独で確定する指標ではない。","priority":100},{"sourceId":"kb_017","targetId":"kb_970","type":"related","reviewStatus":"confirmed","rationale":"選択的注意とカクテルパーティー効果は説明対象・手法を区別しながら読める。注意の一般的な選択機能。非注意性盲目はその結果生じうる個別現象として区別。","priority":100},{"sourceId":"kb_872","targetId":"kb_970","type":"related","reviewStatus":"confirmed","rationale":"選択的注意と非注意性盲目は説明対象・手法を区別しながら読める。注意の一般的な選択機能。非注意性盲目はその結果生じうる個別現象として区別。","priority":100},{"sourceId":"kb_874","targetId":"kb_970","type":"related","reviewStatus":"confirmed","rationale":"選択的注意と注意の瞬きは説明対象・手法を区別しながら読める。注意の一般的な選択機能。非注意性盲目はその結果生じうる個別現象として区別。","priority":100},{"sourceId":"kb_450","targetId":"kb_971","type":"related","reviewStatus":"confirmed","rationale":"心的回転とパターン認識は説明対象・手法を区別しながら読める。追加発見候補から採用。頻度錯覚の代替。","priority":100},{"sourceId":"kb_742","targetId":"kb_971","type":"related","reviewStatus":"confirmed","rationale":"心的回転と二重符号化理論は説明対象・手法を区別しながら読める。追加発見候補から採用。頻度錯覚の代替。","priority":100},{"sourceId":"kb_414","targetId":"kb_972","type":"related","reviewStatus":"confirmed","rationale":"スキーマ理論と連想ネットワークは説明対象・手法を区別しながら読める。Bartlett、Piagetらに連なる複数の用法。単一提唱者の万能理論にしない。","priority":100},{"sourceId":"kb_596","targetId":"kb_972","type":"related","reviewStatus":"confirmed","rationale":"スキーマ理論と確証バイアスは説明対象・手法を区別しながら読める。Bartlett、Piagetらに連なる複数の用法。単一提唱者の万能理論にしない。","priority":100},{"sourceId":"kb_858","targetId":"kb_972","type":"related","reviewS