update public.techniques t set theory_ids=t.theory_ids||jsonb_build_array(l.theory_id),updated_at=now() from release_technique_links l where t.id=l.technique_id;
set constraints all immediate;
do $verify$ declare counts jsonb;begin
 select jsonb_object_agg(category_id,n) into counts from(select category_id,count(*) n from public.theories where status='published' group by category_id) q;
 if counts<>'{"psychology":405,"behavioral-science":146,"organization-management":131,"strategy":94,"practical-wisdom":79,"classics-thought":90}'::jsonb then raise exception 'Category totals differ: %',counts;end if;
 if (select count(*) from public.theories where status='published' and access_tier='free')<>141 then raise exception 'Free access changed';end if;
 if (select count(*) from public.theory_subcategories)<>36 or (select count(*) from public.theory_relations)<>916 then raise exception 'Taxonomy/network drift';end if;
 if exists(select 1 from public.theories t join release_cards c using(id) where t.aliases<>c.aliases or t.display_id<>c.display_id or t.taxonomy_order<>c.taxonomy_order or not(t.related_theory_ids @> c.related_theory_ids and c.related_theory_ids @> t.related_theory_ids)) then raise exception 'Generated catalog differs from DB';end if;
 if exists(select 1 from public.theories t join release_new_ids n using(id) left join public.paid_content p on p.content_id=t.id and p.content_type='theory' where p.content_id is null or p.payload->>'summary'<>t.summary or p.payload->'provenance'<>t.provenance or p.payload->'aliases'<>t.aliases) then raise exception 'Paid projection mismatch';end if;
 if exists(select 1 from private.theory_reform_backups b join public.theories t on t.id=b.source_id where b.phase='theory-release-20261018' and b.source_table='theories' and (b.snapshot-'aliases'-'related_theory_ids'-'display_id'-'display_order'-'taxonomy_order'-'updated_at'-'updated_by')<>(to_jsonb(t)-'aliases'-'related_theory_ids'-'display_id'-'display_order'-'taxonomy_order'-'updated_at'-'updated_by')) then raise exception 'Existing content/identity changed';end if;
end $verify$;
-- After-images make rollback refuse to overwrite subsequent CMS edits.
insert into private.theory_reform_backups(phase,source_table,source_id,snapshot)
 select 'theory-release-20261018-after','theories',id,to_jsonb(t) from public.theories t
 union all select 'theory-release-20261018-after','theory_relations',source_id||'|'||target_id,to_jsonb(r) from public.theory_relations r
 union all select 'theory-release-20261018-after','techniques',id,to_jsonb(t) from public.techniques t where id in(select technique_id from release_technique_links);
commit;
